/* ================= Armazenamento ================= */
const K={season:"girabolaCraque.v1",prefs:"girabolaCraque.prefs",career:"girabolaCraque.career",oldDiff:"girabolaCraque.v1.diff",backup:"girabolaCraque.v1.backup"};
let STORAGE_OK=true;
try{const k="__gc_probe";localStorage.setItem(k,"1");localStorage.removeItem(k)}catch(e){STORAGE_OK=false}
function sGet(k){if(!STORAGE_OK)return null;try{return localStorage.getItem(k)}catch(e){return null}}
let SAVE_FAILED=false;
function saveWarning(){SAVE_FAILED=true;if(!document.body)return;let el=document.getElementById("saveWarning");if(!el){el=document.createElement("div");el.id="saveWarning";el.setAttribute("role","alert");el.style.cssText="position:fixed;bottom:12px;left:12px;right:12px;z-index:9999;background:#7c2020;color:white;padding:12px;border-radius:8px";document.body.appendChild(el)}el.textContent="Não foi possível guardar o progresso. Exporte uma cópia em Dados antes de fechar o jogo."}
function sSet(k,v){if(!STORAGE_OK){saveWarning();return false}try{localStorage.setItem(k,v);return true}catch(e){saveWarning();return false}}

/* Preferências */
const DEFAULT_KEYS={up:["KeyW","ArrowUp"],down:["KeyS","ArrowDown"],left:["KeyA","ArrowLeft"],right:["KeyD","ArrowRight"],pass:["KeyX",""],shoot:["Space",""],switch:["KeyC",""],sprint:["ShiftLeft","ShiftRight"],pause:["KeyP","Escape"],dribble:["KeyZ",""],cancel:["KeyV",""]};
const ACTIONS=[["up","Mover para cima"],["down","Mover para baixo"],["left","Mover para a esquerda"],["right","Mover para a direita"],["pass","Passe"],["shoot","Remate (com bola) / desarme (sem bola)"],["switch","Trocar de jogador"],["sprint","Sprint"],["dribble","Drible (mais lento, bola junto ao pé)"],["cancel","Cancelar passe ou remate carregado"],["pause","Pausa"]];
function defaultPrefs(){let rm=false;try{rm=matchMedia("(prefers-reduced-motion: reduce)").matches}catch(e){}
  return{v:1,fatigue:true,shotTiming:false,timingWin:90,diff:"normal",keys:JSON.parse(JSON.stringify(DEFAULT_KEYS)),autoSwitch:"assist",reduceFx:rm,replays:true,rules:"classic",tactic:"bal",form:"221",legs:1,sound:true,tutorialSeen:false,camera:"tv",camZoom:1,offsideVar:true,daytime:"night",stadium:"imbondeiro",crowd:"auto",ballDesign:"auto",musicVol:.15,musicVolV:2,sfxVol:.9,crowdVol:.8,musicStyle:"auto",gameMusic:"low",passAssist:"assist",shotStyle:"power",quality:"high",touchScale:1}}
function loadPrefs(){
  const d=defaultPrefs(),raw=parseJSON(sGet(K.prefs)||"null");
  if(raw&&typeof raw==="object"&&!Array.isArray(raw)){
    if(DIFF[raw.diff])d.diff=raw.diff;
    if(raw.keys&&typeof raw.keys==="object")for(const a in DEFAULT_KEYS){const v=raw.keys[a];if(Array.isArray(v)&&v.length===2&&v.every(x=>typeof x==="string"&&/^([A-Za-z][A-Za-z0-9]{0,39})?$/.test(x)))d.keys[a]=v.slice()}
    if(raw.autoSwitch==="manual"||raw.autoSwitch==="assist")d.autoSwitch=raw.autoSwitch;
    for(const k of ["reduceFx","replays","sound","tutorialSeen","offsideVar","uiSfx","fatigue","shotTiming"])if(typeof raw[k]==="boolean")d[k]=raw[k];
    if(RULES[raw.rules])d.rules=raw.rules; if(TACTICS[raw.tactic])d.tactic=raw.tactic; if(FORMS[raw.form])d.form=raw.form;
    if(raw.legs===1||raw.legs===2)d.legs=raw.legs;
    if(raw.daytime==="day"||raw.daytime==="night")d.daytime=raw.daytime;
    if(["auto","off","low","med","high"].includes(raw.crowd))d.crowd=raw.crowd;
    if(["auto","rubro_negra","angola","azul","classica","verde"].includes(raw.ballDesign))d.ballDesign=raw.ballDesign;
    raw.stadium=({classic:"classico",modern:"imbondeiro",arena:"imbondeiro",aberto:"azul"})[raw.stadium]||raw.stadium;
    if(["imbondeiro","classico","azul","marcal","bairro"].includes(raw.stadium))d.stadium=raw.stadium;
    if(raw.camera==="tv"||raw.camera==="top")d.camera=raw.camera;
    if(typeof raw.intro==="boolean")d.intro=raw.intro;
    if(typeof raw.camZoom==="number"&&raw.camZoom>=.5&&raw.camZoom<=2.5)d.camZoom=raw.camZoom;
    for(const k of ["musicVol","sfxVol","crowdVol","ballVol","refVol","uiVol"])if(typeof raw[k]==="number"&&raw[k]>=0&&raw[k]<=1)d[k]=raw[k];
    /* a música passou a arrancar a 15%: quem ainda tem o volume antigo guardado (versão < 2) é passado para o novo */
    if(raw.musicVolV!==2){d.musicVol=.15}d.musicVolV=2;
    if(["auto","semba","kizomba","kuduro","off","faixas","gerada"].includes(raw.musicStyle))d.musicStyle=raw.musicStyle;
    if(["low","normal","off"].includes(raw.gameMusic))d.gameMusic=raw.gameMusic;
    if([60,90,140].includes(raw.timingWin))d.timingWin=raw.timingWin;
    if(["assist","manual"].includes(raw.passAssist))d.passAssist=raw.passAssist;
    if(["power","placed"].includes(raw.shotStyle))d.shotStyle=raw.shotStyle;
    if(["low","medium","high"].includes(raw.quality))d.quality=raw.quality;
    if([1,1.15,1.3].includes(raw.touchScale))d.touchScale=raw.touchScale;
  }else{const od=sGet(K.oldDiff);if(DIFF[od])d.diff=od}
  return d;
}
let PREF=loadPrefs();
function savePrefs(){sSet(K.prefs,JSON.stringify(PREF))}

/* ================= Época ================= */
let S=null, SEASON_BAD=false;
function roundRobin(ids){const n=ids.length,arr=ids.slice(),rounds=[];for(let r=0;r<n-1;r++){const m=[];for(let i=0;i<n/2;i++){const a=arr[i],b=arr[n-1-i];m.push((r+i)%2?[a,b]:[b,a])}rounds.push(m);arr.splice(1,0,arr.pop())}return rounds}
function makeFixtures(legs){const ids=TEAMS.slice(0,BASE_N).map((_,i)=>i).sort(()=>Math.random()-.5);const first=roundRobin(ids);return legs===2?first.concat(first.map(r=>r.map(([h,a])=>[a,h]))):first}
function newId(){return (Date.now().toString(36)+Math.random().toString(36).slice(2,8)).slice(0,20)}
function emptyTable(){const t={};TEAMS.slice(0,BASE_N).forEach((_,i)=>t[i]={P:0,W:0,D:0,L:0,F:0,A:0,Pts:0});return t}
function poisson(l){const L=Math.exp(-l);let k=0,p=1;do{k++;p*=Math.random()}while(p>L);return k-1}
function simScore(h,a){const d=(TEAMS[h].r-TEAMS[a].r)/22;const lh=clamp(1.25*Math.exp(d)+.15,.25,3.2),la=clamp(1.05*Math.exp(-d),.2,3);return[poisson(lh),poisson(la)]}
function saveSeason(){if(S)sSet(K.season,JSON.stringify(S))}
function validateSeason(o){
  const err=m=>({ok:false,err:m});
  if(!o||typeof o!=="object"||Array.isArray(o))return err("O ficheiro não contém uma época válida.");
  if(!isInt(o.my,0,15))return err("A equipa escolhida não é válida.");
  if(!Array.isArray(o.fix)||(o.fix.length!==15&&o.fix.length!==30))return err("O calendário tem de ter 15 ou 30 jornadas.");
  for(const r of o.fix){
    if(!Array.isArray(r)||r.length!==8)return err("Uma das jornadas do calendário está incompleta.");
    const seen=new Set();
    for(const m of r){
      if(!Array.isArray(m)||m.length!==2||!isInt(m[0],0,15)||!isInt(m[1],0,15)||m[0]===m[1])return err("Há um jogo inválido no calendário.");
      if(seen.has(m[0])||seen.has(m[1]))return err("Uma equipa aparece duas vezes na mesma jornada.");
      seen.add(m[0]);seen.add(m[1]);
    }
  }
  for(let leg=0;leg<o.fix.length/15;leg++){
    const pairs=new Set();for(const r of o.fix.slice(leg*15,leg*15+15))for(const [h,a] of r){const key=Math.min(h,a)+":"+Math.max(h,a);if(pairs.has(key))return err("Há confrontos repetidos na mesma volta.");pairs.add(key)}
    if(pairs.size!==120)return err("Faltam confrontos na volta.");
  }
  if(o.fix.length===30){const first=new Set(o.fix.slice(0,15).flat().map(([h,a])=>h+":"+a));for(const [h,a] of o.fix.slice(15).flat())if(!first.has(a+":"+h))return err("A segunda volta não inverte casa e fora.");}
  if(!isInt(o.round,0,o.fix.length))return err("A jornada atual não é válida.");
  if(!o.table||typeof o.table!=="object")return err("Falta a classificação.");
  const table={};
  for(let i=0;i<16;i++){
    const r=o.table[i];if(!r||typeof r!=="object")return err("Falta uma equipa na classificação.");
    const row={};for(const k of ["P","W","D","L","F","A","Pts"]){if(!isInt(r[k],0,9999))return err("Há valores inválidos na classificação.");row[k]=r[k]}
    if(row.W+row.D+row.L!==row.P||row.Pts!==row.W*3+row.D||row.P!==o.round)return err("A classificação não bate certo com as jornadas disputadas.");
    table[i]=row;
  }
  const total=k=>Object.values(table).reduce((n,r)=>n+r[k],0);
  if(total("F")!==total("A")||total("W")!==total("L")||total("D")%2)return err("Os totais globais da classificação são incoerentes.");
  let last=null;
  if(o.last&&typeof o.last==="object"&&isInt(o.last.round,0,29)&&Array.isArray(o.last.res)&&o.last.res.length===8&&o.last.res.every(x=>Array.isArray(x)&&x.length===4&&isInt(x[0],0,15)&&isInt(x[1],0,15)&&isInt(x[2],0,99)&&isInt(x[3],0,99)))last={round:o.last.round,res:o.last.res.map(x=>x.slice())};
  return{ok:true,season:{v:2,id:typeof o.id==="string"&&/^[a-z0-9]{4,24}$/i.test(o.id)?o.id:newId(),my:o.my,legs:o.fix.length===30?2:1,round:o.round,fix:o.fix.map(r=>r.map(m=>m.slice())),table,last,recorded:o.recorded===true,started:typeof o.started==="string"?o.started.slice(0,40):null}};
}
(function loadSeason(){
  const raw=sGet(K.season);if(!raw)return;
  const o=parseJSON(raw),v=validateSeason(o);
  if(v.ok){S=v.season;if(!o.v||o.v<2||!o.id)saveSeason()} // migração da versão 1
  else{SEASON_BAD=true;sSet(K.backup,raw)}
})();
function newSeason(my,legs){S={v:2,id:newId(),my,legs,round:0,fix:makeFixtures(legs),table:emptyTable(),last:null,recorded:false,started:new Date().toISOString()};SEASON_BAD=false;saveSeason()}
function record(h,a,gh,ga){const H=S.table[h],A=S.table[a];H.P++;A.P++;H.F+=gh;H.A+=ga;A.F+=ga;A.A+=gh;if(gh>ga){H.W++;A.L++;H.Pts+=3}else if(gh<ga){A.W++;H.L++;A.Pts+=3}else{H.D++;A.D++;H.Pts++;A.Pts++}}
const seasonDone=()=>S&&S.round>=S.fix.length;
function myFixture(){return S.fix[S.round].find(m=>m.includes(S.my))}
function completeRound(mine,played){
  if(!S||seasonDone())return;
  const res=[];
  for(const [h,a] of S.fix[S.round]){let gh,ga;if(h===S.my||a===S.my){gh=mine.gh;ga=mine.ga}else{[gh,ga]=simScore(h,a)}record(h,a,gh,ga);res.push([h,a,gh,ga])}
  S.last={round:S.round,res};S.round++;
  const [fh]=res.find(m=>m[0]===S.my||m[1]===S.my),my=fh===S.my?mine.gh:mine.ga,op=fh===S.my?mine.ga:mine.gh;
  const xp=matchXP(my,op)*(played?1:.4);
  C.xp+=Math.round(xp);
  if(played){C.played++;C.goals+=my;if(my>op)C.W++;else if(my<op)C.L++;else C.D++}
  saveCareer();saveSeason();
  if(seasonDone())finalizeSeason();
  return Math.round(xp);
}
function sortedTable(){return Object.entries(S.table).map(([id,r])=>({id:+id,...r})).sort((x,y)=>y.Pts-x.Pts||(y.F-y.A)-(x.F-x.A)||y.F-x.F||TEAMS[x.id].n.localeCompare(TEAMS[y.id].n))}

/* ================= Carreira ================= */
function defaultCareer(){return{v:1,xp:0,played:0,W:0,D:0,L:0,goals:0,titles:{},seasons:[],cos:{ball:"classica",marker:"ouro",confetti:"bandeira"}}}
function loadCareer(){
  const d=defaultCareer(),r=parseJSON(sGet(K.career)||"null");
  if(!r||typeof r!=="object"||Array.isArray(r))return d;
  for(const k of ["xp","played","W","D","L","goals"])if(isInt(r[k],0,1e9))d[k]=r[k];
  if(r.titles&&typeof r.titles==="object")for(let i=0;i<16;i++){const v=r.titles[i];if(isInt(v,0,9999))d.titles[i]=v}
  if(Array.isArray(r.seasons)){const ids=new Set();d.seasons=r.seasons.filter(x=>x&&typeof x.id==="string"&&!ids.has(x.id)&&ids.add(x.id)&&isInt(x.team,0,15)&&isInt(x.pos,1,16)&&isInt(x.pts,0,999)&&(x.legs===1||x.legs===2)).slice(-100).map(x=>({id:x.id,team:x.team,pos:x.pos,pts:x.pts,legs:x.legs,champ:isInt(x.champ,0,15)?x.champ:x.team,end:typeof x.end==="string"?x.end.slice(0,40):""}))}
  if(r.cos&&typeof r.cos==="object")for(const k in d.cos){if(COSM[k].some(c=>c.id===r.cos[k]))d.cos[k]=r.cos[k]}
  return d;
}
let C=loadCareer();
function saveCareer(){sSet(K.career,JSON.stringify(C))}
const level=()=>1+Math.floor(C.xp/150);
const matchXP=(my,op)=>(my>op?30:my===op?15:5)+5*Math.min(my,6);
function finalizeSeason(){
  if(!seasonDone())return;
  if(S.recorded||C.seasons.some(x=>x.id===S.id)){if(!S.recorded){S.recorded=true;saveSeason()}return}
  const tab=sortedTable(),pos=tab.findIndex(r=>r.id===S.my)+1,champ=tab[0].id;
  C.seasons.push({id:S.id,team:S.my,pos,pts:S.table[S.my].Pts,legs:S.legs,champ,end:new Date().toISOString()});
  C.titles[champ]=(C.titles[champ]||0)+1;
  C.xp+=pos===1?200:pos<=3?80:30;
  saveCareer();S.recorded=true;saveSeason();
}
