function assignIdentity(p,athlete){p.rosterId=athlete.id;p.fullName=athlete.fullName;p.name=athlete.name;p.num=athlete.num;p.positionSource=athlete.positionSource}

function createMatch(o){
  const tL=TEAMS[o.L],tR=TEAMS[o.R],styleR=tR.st,formR=STYLES[styleR].form,D=DIFF[o.diff]||DIFF.normal;
  let cR={c1:tR.c1,c2:tR.c2};
  if(colorDist(tL.c1,tR.c1)<120)cR={c1:tR.c2,c2:tR.c1};
  if(colorDist(tL.c1,cR.c1)<120)cR={c1:"#f2f2f2",c2:tR.c1};
  const players=[];
  const mk=(t,form,rt,sp)=>FORMS[form].p.forEach(([role,x,y,num],i)=>players.push({team:t,i,role,hx:x,hy:y,bx:x,by:y,num,x:0,y:0,vx:0,vy:0,dx:0,dy:0,fx:t?-1:1,fy:0,kickCd:0,stun:0,dash:0,dashx:0,dashy:0,tackling:false,gkHold:0,rating:rt,sp,energy:1,tired:false,sprint:false,sprinting:false,run:0,job:"hold",think:Math.random()*.3,off:false}));
  mk(0,FORMS[o.form]?o.form:"221",tL.r,2.42*(.93+(tL.r-60)/220));
  mk(1,formR,tR.r,2.32*(.88+(tR.r-60)/160)*D.speed);
  const used=[new Set(),new Set()];
  for(const p of players){const roster=SQUADS[(p.team===0?tL:tR).n],pool=roster.filter(a=>a.role===p.role&&!used[p.team].has(a.id));const a=pool.find(a=>a.num===p.num)||pool[0]||roster.find(a=>!used[p.team].has(a.id));assignIdentity(p,a);used[p.team].add(a.id);p.baseSp=p.sp;p.rating=clamp(p.rating+(p.i%3-1)*3,40,95);p.sp*=1+(p.i%3-1)*.035;p.subbed=false}

  return{o,D,styleR,formR,teams:[tL,tR],cols:[{c1:tL.c1,c2:tL.c2},cR],players,
    ball:{x:W/2,y:H/2,vx:0,vy:0,z:0,vz:0,sp:0,owner:null,lastTeam:0,last:null,pend:null},
    score:[0,0],t:0,state:"kickoff",st:0,half:1,ctrl:null,switchLock:0,autoLock:0,charge:0,charging:false,needRelease:false,tackleCd:0,
    msg:"",msgSub:"",paused:false,shake:0,flash:0,ended:false,parts:[],trail:[],hot:0,slow:0,net:null,flashT:0,
    stats:[mkStats(),mkStats()],brainT:[0,.1],rb:new Float32Array(RF*RN),rbHead:0,rbCount:0,replay:null,goalRec:0,setp:null,
    passTarget:null,aim:null,tickPT:0,switches:0,firstKick:o.homeLeft?0:1,events:[],stadium:STADIUM_INFO[PREF.stadium][0],subs:0,tut:null};
}

function setupKickoff(team){
  const b=G.ball;b.x=W/2;b.y=H/2;b.vx=b.vy=0;b.owner=null;b.pend=null;
  for(const p of G.players){p.x=pxOf(p.team,Math.min(p.hx,.44));p.y=pyOf(p.hy);p.vx=p.vy=p.dx=p.dy=0;p.stun=0;p.kickCd=0;p.kickAnim=0;p.dash=0;p.tackling=false;p.dive=null;p.gkDown=0;p.gkJump=0;p.fx=sd(p.team)?-1:1;p.fy=0;p.bx=p.hx;p.by=p.hy}
  const f=G.players.find(p=>p.team===team&&!p.off&&p.role==="F")||nearestOf(team,b,false)||G.players.find(p=>p.team===team&&!p.off);
  f.x=W/2+(sd(team)===0?-13:13);f.y=H/2;b.owner=f;b.lastTeam=team;b.last=f;
  G.state="kickoff";G.st=1.1;G.charge=0;G.charging=false;G.msg="";G.trail.length=0;G.hot=0;G.setp=null;
  setCtrl(team===0?f:nearestOf(0,b,false));
  teamBrain(0);teamBrain(1);
}
function nearestOf(team,pt,gk,ex){let best=null,bd=1e9;for(const p of G.players){if(p.off||p.team!==team||(!gk&&p.role==="GK")||p===ex)continue;const d=dist(p,pt);if(d<bd){bd=d;best=p}}return best}
function predictBall(f){const b=G.ball;if(b.owner)return{x:b.x+b.owner.vx*f*.6,y:b.y+b.owner.vy*f*.6};const k=(1-Math.pow(.978,f))/.022;return{x:b.x+b.vx*k,y:b.y+b.vy*k}}
function minOppDist(p){let m=1e9;for(const q of G.players)if(!q.off&&q.team!==p.team)m=Math.min(m,dist(p,q));return m}
const minute=()=>Math.min(90,Math.floor(G.t/MATCH_LEN*90));
function seek(p,tx,ty,scale){const dx=tx-p.x,dy=ty-p.y,d=Math.hypot(dx,dy);if(d<1){p.dx=p.dy=0;return}let sp=p.sp*(scale||1)*(G.ball.owner===p?.9:1);if(d<24)sp*=d/24;p.dx=dx/d*sp;p.dy=dy/d*sp}
function setCtrl(p){if(!p)return;if(G.ctrl&&G.ctrl!==p)G.ctrl.sprint=false;G.ctrl=p;G.charge=0;G.charging=false}
function laneClear(p,q,r){const ax=q.x-p.x,ay=q.y-p.y,L=ax*ax+ay*ay||1;for(const o of G.players){if(o.off||o.team===p.team)continue;const t=((o.x-p.x)*ax+(o.y-p.y)*ay)/L;if(t<0||t>1)continue;if(Math.hypot(p.x+ax*t-o.x,p.y+ay*t-o.y)<(r||20))return false}return true}

/* ---------- Ciclo ---------- */
function step(){
  if(!G||G.paused)return;
  updateFx();
  for(const p of G.players)p.kickAnim=Math.max(0,(p.kickAnim||0)-DT);
  G.flash=Math.max(0,G.flash-DT);G.shake=Math.max(0,G.shake-DT);
  if(G.state!=="play"&&G.state!=="goal"&&G.state!=="replay"){const bb=G.ball;if(bb.z>0||bb.vz||bb.sp){bb.z=0;bb.vz=0;bb.sp=0}}
  switch(G.state){
    case "play":stepPlay();break;
    case "kickoff":G.st-=DT;if(G.st<=0){G.state="play";G.msg="";sfx("whistle")}break;
    case "goal":G.st-=DT;ballPhysics(false);if(G.goalRec<30){recordFrame();G.goalRec++}
      if(G.st<=0){if(PREF.replays&&!G.tut&&G.rbCount>30)startReplay();else setupKickoff(G.nextKick)}break;
    case "replay":if(input.shootPressed||input.passPressed){endReplay();break}G.replay.f+=PREF.reduceFx?1:.55;if(G.replay.f>=G.replay.n-1)endReplay();break;
    case "setpiece":stepSetPiece();break;
    case "half":if(input.shootPressed||input.passPressed)startSecondHalf();break;
    case "end":G.st-=DT;if(G.st<=0&&!G.ended){G.ended=true;finishMatch()}break;
  }
  input.shootPressed=input.passPressed=input.switchPressed=input.cancelPressed=false;
}
function stepPlay(){
  G.t+=DT;
  if(!G.tut){
    if(G.half===1&&G.t>=MATCH_LEN/2){toHalf();return}
    if(G.t>=MATCH_LEN){toEnd();return}
  }
  G.switchLock-=DT;G.autoLock-=DT;G.tackleCd-=DT;
  for(const p of G.players){if(p.off)continue;p.kickCd-=DT;p.stun-=DT;p.think-=DT;p.dash-=DT;p.gkHold-=DT;if(p.gkJump>0)p.gkJump-=DT;if(p.gkDown>0){p.gkDown-=DT;if(p.dive)p.dive.t+=DT;if(p.gkDown<=0)p.dive=null}if(p.dash<=0){if(p.tackling){if(p.tkSlide){p.stun=Math.max(p.stun,.3+.35*(p.tkSp||0));if(G.tk)G.tk.miss++}else p.kickCd=Math.max(p.kickCd,.25)}p.tackling=false}}
  brains();
  updateControl();
  if(!G.auto)humanInput();
  for(const p of G.players)if(!p.off&&(p!==G.ctrl||G.auto))ai(p);
  movePlayers();
  separate();
  ballPhysics(true);
  if(G.state==="play")tackles();
  const b=G.ball;
  const possTeam=b.owner?b.owner.team:b.pend&&b.pend.type==="pass"?b.pend.team:null;
  if(possTeam!==null)G.stats[possTeam].poss+=DT;
  if(G.ctrl&&b.owner===G.ctrl){if(--G.tickPT<=0){G.tickPT=3;G.passTarget=choosePassTarget(G.ctrl)}}else G.passTarget=null;
  if(G.state==="play")recordFrame();
  if(G.tut)tutStep();
}
function brains(){for(let t=0;t<2;t++){G.brainT[t]-=DT;if(G.brainT[t]<=0){G.brainT[t]=t===1?Math.max(.15,G.D.think*.75):.22;teamBrain(t)}}}
function toHalf(){G.state="half";G.msg="";G.ball.owner=null;G.ball.pend=null;sfx("whistle",2);showHalf()}
function startSecondHalf(){if(!G||G.state!=="half")return;hideOverlay();for(const p of G.players)p.stam=Math.min(1,(p.stam==null?1:p.stam)+.3);   // o intervalo repõe parte do fôlego
  G.half=2;G.swap=true;G.t=MATCH_LEN/2;setupKickoff(1-G.firstKick)}
function toEnd(){G.t=MATCH_LEN;G.state="end";G.st=2.2;G.msg="Apito final";G.msgSub=`${G.teams[0].s} ${G.score[0]} – ${G.score[1]} ${G.teams[1].s}`;G.ball.owner=null;G.ball.pend=null;sfx("whistle",3)}

/* roda a orientação (p.hd, em radianos) para o alvo com velocidade limitada: rápida parado, mais lenta em sprint; sincroniza se fx/fy foram mudados de fora */
function turnHeading(p,wx,wy){
  if(p.hd===undefined||Math.hypot(p.fx-Math.cos(p.hd),p.fy-Math.sin(p.hd))>.02)p.hd=Math.atan2(p.fy,p.fx);
  p.turn=0;
  if(wx==null||p.dash>0)return;
  const sp=Math.hypot(p.vx,p.vy),mx=Math.max(1,p.sp*1.38),rate=(13-6.5*clamp(sp/mx,0,1))*(p.stun>0?.2:1)*(p.role==="GK"?.85:1)*(p.dribble?1.5:1);
  let d=Math.atan2(wy,wx)-p.hd;d=Math.atan2(Math.sin(d),Math.cos(d));
  const st=clamp(d,-rate*DT,rate*DT);p.hd+=st;p.turn=Math.abs(st);
  p.fx=Math.cos(p.hd);p.fy=Math.sin(p.hd);
}
function movePlayers(){
  for(const p of G.players){
    if(p.off)continue;
    const moving=Math.hypot(p.dx,p.dy)>.4;
    if(p.tired&&p.energy>.3)p.tired=false;
    const spr=p.sprint&&moving&&!p.tired&&p.energy>0&&p.stun<=0&&!p.dribble;
    const fat=PREF.fatigue!==false&&!G.tut,st=p.stam==null?1:p.stam;
    if(fat){const run=Math.hypot(p.vx,p.vy)/Math.max(1,p.sp);p.stam=clamp(st-DT*run*.0028*(spr?1.7:1)+(run<.25?DT*.004:0),.4,1)}      // fôlego: desce devagar com a corrida e recupera um pouco quando abranda; mínimo 40%
    if(spr){p.energy-=.3*DT*(fat?1+(1-st)*.5:1);if(p.energy<=0){p.energy=0;p.tired=true}}
    else p.energy=Math.min(1,p.energy+(moving?.07:.16)*DT);
    p.sprinting=spr;
    const f=(spr?1.38:1)*(.88+.12*Math.min(1,p.energy/.25))*(fat?.9+.1*st:1)*(p.dribble?.64:1);
    const k=p.dash>0?.4:.2;
    if(p.dive){const d=p.dive,rem=d.ty-p.y;if(d.t<d.dur&&rem*d.side>.8)p.vy=d.side*Math.min(d.v,Math.abs(rem)*.5+.7);else p.vy*=.82;p.vx*=.9}
    else if(p.dash>0){p.vx+=(p.dx*f-p.vx)*k;p.vy+=(p.dy*f-p.vy)*k}
    else{
      // aceleração gradual, travagem mais rápida e inversões de marcha custosas (como um corpo real)
      const tx=p.dx*f,ty=p.dy*f,ex=tx-p.vx,ey=ty-p.vy,em=Math.hypot(ex,ey),sp0=Math.hypot(p.vx,p.vy),spT=Math.hypot(tx,ty);
      let lim=spT>=sp0?.1:.19;
      if(sp0>.8&&spT>.3&&(p.vx*tx+p.vy*ty)/(sp0*spT)<.3)lim=.24;
      lim*=(p.role==="GK"?1.25:1)*(1+.1*(p.rating-60)/40)*(fat?.85+.15*st:1);      // cansado acelera menos
      if(em>lim){p.vx+=ex/em*lim;p.vy+=ey/em*lim}else{p.vx=tx;p.vy=ty}
    }
    if(p.stun>0){p.vx*=.85;p.vy*=.85}
    p.run+=Math.hypot(p.vx,p.vy)*.28;
    /* junto às linhas: desacelera ao aproximar-se; pode passar a linha por inércia (até 10 u) e é travado fora dela; o portador não conduz a bola para fora */
    if(G.state==="play"&&p.role!=="GK"&&!G.tut){
      const ownr=G.ball.owner===p,inGoal=Math.abs(p.y-H/2)<GH/2+4;
      const fx=(pos,v,lo,hi,own)=>{      // v<0 aproxima-se de lo; v>0 de hi
        const dd=v<0?pos-lo:hi-pos;
        if(dd<0)return .78;
        if(own&&dd<36)return 1-(1-clamp((dd-16)/20,0,1))*.45;
        return dd<14?.9+.1*dd/14:1};
      if(p.vx!==0)p.vx*=fx(p.x,p.vx,X0,X1,ownr&&!inGoal);
      if(p.vy!==0)p.vy*=fx(p.y,p.vy,Y0,Y1,ownr);
    }
    if(G.state==="play"&&p.role!=="GK"&&!G.tut&&G.ball.owner===p){      // o portador fica sempre ≥ 15 u dentro das linhas (fora da baliza)
      const inGoal=Math.abs(p.y-H/2)<GH/2+4;
      p.x=inGoal?clamp(p.x+p.vx,X0-10,X1+10):clamp(p.x+p.vx,X0+15,X1-15);p.y=clamp(p.y+p.vy,Y0+15,Y1-15);
    }else if(G.state==="play"&&p.role!=="GK"&&!G.tut){p.x=clamp(p.x+p.vx,X0-10,X1+10);p.y=clamp(p.y+p.vy,Y0-10,Y1+10)}
    else{p.x=clamp(p.x+p.vx,X0+6,X1-6);p.y=clamp(p.y+p.vy,Y0+6,Y1-6)}
    const s=Math.hypot(p.vx,p.vy);
    if(p===G.ctrl&&!G.auto)turnHeading(p,p.wx,p.wy);
    else if(s>.35&&!(p.role==="GK"&&G.ball.owner===p)&&p.dash<=0)turnHeading(p,p.vx/s,p.vy/s);
    else turnHeading(p,null,null);
    p.turnAcc=(p.turnAcc||0)*.9+(p.turn||0);
  }
}
function separate(){const P=G.players;for(let i=0;i<P.length;i++){const a=P[i];if(a.off)continue;for(let j=i+1;j<P.length;j++){const c=P[j];if(c.off)continue;const dx=c.x-a.x,dy=c.y-a.y,d=Math.hypot(dx,dy);if(d>0&&d<19){const k=(19-d)/d*.5;a.x-=dx*k;a.y-=dy*k;c.x+=dx*k;c.y+=dy*k}}}}

/* ---------- Controlo humano ---------- */
function updateControl(){
  const b=G.ball,o=b.owner;
  if(o&&o.team===0){if(o.role!=="GK"&&G.ctrl!==o)setCtrl(o);return}
  if(!o&&b.pend&&b.pend.type==="pass"&&b.pend.team===0&&b.pend.to&&b.pend.to!==G.ctrl&&b.pend.to.role!=="GK"&&!b.pend.to.off){setCtrl(b.pend.to);return}
  if(!G.ctrl||G.ctrl.off){setCtrl(nearestOf(0,b,false));return}
  if(PREF.autoSwitch!=="assist"||G.tut||G.switchLock>0||G.autoLock>0)return;
  const n=nearestOf(0,predictBall(8),false);
  if(n&&n!==G.ctrl&&dist(G.ctrl,b)>170&&dist(n,b)+110<dist(G.ctrl,b)){setCtrl(n);G.autoLock=1.2}
}
function humanInput(){
  const p=G.ctrl;if(!p)return;const b=G.ball;
  let ix=input.x,iy=input.y,m=Math.hypot(ix,iy);if(m>1){ix/=m;iy/=m;m=1}
  p.sprint=input.sprint;
  if(p.stun>0){p.dx=p.dy=0}
  else if(p.dash>0){p.dx=p.dashx;p.dy=p.dashy}
  else{const sp=p.sp*(b.owner===p?.92:1);p.dx=ix*sp;p.dy=iy*sp}
  if(m>.15&&p.dash<=0){p.wx=ix/m;p.wy=iy/m}else{p.wx=p.wy=null}          // a orientação roda gradualmente em movePlayers
  let rx=input.tx,ry=input.ty;if(!rx&&!ry){rx=input.x;ry=input.y}          // sem alvo imediato (online): usa o vector recebido
  const rm=Math.hypot(rx,ry);
  G.aim=rm>.3?{x:rx/rm,y:ry/rm}:null;
  const has=b.owner===p;
  if(input.switchPressed&&!has){manualSwitch();return}
  p.dribble=!!input.dribble&&p.stun<=0;
  if(G.tut&&p.dribble&&Math.hypot(p.vx,p.vy)>.5)G.tut.dr=(G.tut.dr||0)+DT;
  if(!has){G.passCharge=null;if(G.pendShot){G.pendShot=null;p.kickAnim=0}}
  /* passe: toque curto = passe normal (moderado, fácil de receber); manter e largar = passe tenso (mais rápido, mais difícil de dominar); V cancela antes de largar */
  if(input.passPressed)G.passBuffer=.20;
  if((G.passBuffer||0)>0){G.passBuffer=Math.max(0,G.passBuffer-DT);if(has&&!G.passCharge){G.passBuffer=0;if(input.passHeld)G.passCharge={t:0};else{humanPass(p,0);return}}}
  if(G.passCharge&&has){
    G.passCharge.t+=DT;
    if(input.cancelPressed){G.passCharge=null;if(G.tut)G.tut.cancel=true}
    else if(!input.passHeld||G.passCharge.t>=.7){const t=G.passCharge.t;G.passCharge=null;humanPass(p,t);return}
  }
  /* remate com temporização (opcional): entre largar e o contacto há uma janela em que um segundo toque melhora a precisão */
  if(G.pendShot){
    const ps=G.pendShot;ps.t+=DT;
    if(input.cancelPressed){G.pendShot=null;p.kickAnim=0;G.needRelease=true;if(G.tut)G.tut.cancel=true}
    else{
      if(input.shootPressed&&ps.tp==null)ps.tp=ps.t;
      if(ps.t>=SHOT_CONTACT){
        const w=(PREF.timingWin||90)/1000,d=ps.tp==null?null:Math.abs(ps.tp-SHOT_CONTACT);
        const nm=d==null?1.1:d<=w?.45:d<=w*2.2?1.5:1.8;      // 1,1 sem segundo toque · .45 no momento certo · 1,5 cedo/tarde · 1,8 muito fora
        G.pendShot=null;shoot(p,ps.c,ps.iy,nm);return}
    }
  }
  if(G.needRelease){if(!input.shootHeld)G.needRelease=false;else return}
  if(has){
    if(G.pendShot||G.passCharge){G.charging=false;G.charge=0}
    else if(input.shootHeld){if(input.cancelPressed){G.charging=false;G.charge=0;G.needRelease=true;if(G.tut)G.tut.cancel=true}else{G.charging=true;G.charge=Math.min(1,G.charge+DT/.75)}}
    else if(G.charging){
      if(PREF.shotTiming&&!G.tut){G.pendShot={c:G.charge,iy:rm>.3?ry/rm:0,t:0,tp:null};p.kickAnim=.65}
      else shoot(p,G.charge,rm>.3?ry/rm:0);
      G.charging=false;G.charge=0}
  }else{
    G.charging=false;G.charge=0;
    if(input.shootPressed&&G.tackleCd<=0&&p.stun<=0){
      const ow=b.owner,aim=ow?{x:b.x+ow.vx*6,y:b.y+ow.vy*6}:{x:b.x+b.vx*5,y:b.y+b.vy*5},tx=aim.x-p.x,ty=aim.y-p.y,d=Math.hypot(tx,ty)||1;
      const sf=Math.hypot(p.vx,p.vy)/Math.max(1,p.sp),slide=(input.sprint||p.sprinting)&&sf>.7;      // em corrida → carrinho (alcance e risco maiores); parado/a andar → desarme em pé
      p.tkSlide=slide;p.tkSp=Math.min(1.4,sf);p.tkDur=slide?.3:.15;p.tkRoll=false;
      p.dash=p.tkDur;const k=slide?2:1.4;p.dashx=tx/d*p.sp*k;p.dashy=ty/d*p.sp*k;p.fx=tx/d;p.fy=ty/d;G.tackleCd=slide?.95:.5;p.tackling=true;p.energy=Math.max(0,p.energy-(slide?.07:.03));
    }
  }
}
function manualSwitch(){
  const b=predictBall(12),score=q=>dist(q,b)+(q.x>b.x?35:0)+(q.stun>0?100:0);
  const c=G.players.filter(q=>q.team===0&&!q.off&&q.role!=="GK"&&q!==G.ctrl).sort((a,q)=>score(a)-score(q));
  if(c[0]){setCtrl(c[0]);G.switchLock=1.5;G.switches++;sfx("switch")}
}
function choosePassTarget(p){
  const dir=G.aim||{x:p.fx,y:p.fy};let best=null,bs=-1e9;
  for(const q of G.players){
    if(q.off||q.team!==p.team||q===p)continue;
    const dx=q.x-p.x,dy=q.y-p.y,d=Math.hypot(dx,dy);if(d<28)continue;
    const dot=(dx*dir.x+dy*dir.y)/d;
    const open=Math.min(minOppDist(q),110)/110,adv=(nxOf(p.team,q.x)-nxOf(p.team,p.x));
    let s=dot*4.2-d/420+(laneClear(p,q,20)?.7:-.9)+open*.9+(G.aim?0:adv*.8)-(q.role==="GK"?1.4:0)-(wouldBeOffside(p,q)?3.5:0);
    if(dot<.35)s-=3;
    if(s>bs){bs=s;best=q}
  }
  return best;
}
function humanPass(p,held){
  if(G.tut&&held>=.22)G.tut.tense=true;
  const q=G.passTarget||choosePassTarget(p),tense=(held||0)>=.22,pw=tense?clamp(((held||0)-.22)/.48,0,1):0,ms=tense?8.8+pw*3:7.4;
  if(PREF.passAssist==="manual"){input.through=false;const a=G.aim||{x:p.fx,y:p.fy};kick(p,p.x+a.x*250,p.y+a.y*250,tense?9+pw*3:6.8,tense?.02:.01);G.ball.pend={type:"pass",team:p.team,from:p,to:null,tense};G.stats[p.team].passA++;return}
  if(!q)return;
  if(input.sprint||input.through){input.through=false;const dr=sd(p.team)===0?1:-1,v0=9,L=leadPoint(p,q,v0,{x:dr*70,y:0}),tx=L.x,ty=L.y;kick(p,tx,ty,clamp(3.5+Math.hypot(tx-p.x,ty-p.y)*.022,6.5,v0),.01);G.ball.pend={type:"pass",team:p.team,from:p,to:q};G.stats[p.team].passA++}else{passTo(p,q,tense?.9:.6,ms,tense?1.3+.4*pw:1);if(tense&&G.ball.pend)G.ball.pend.tense=true}
}

/* ---------- Ações sobre a bola ---------- */
/* qualidade de execução: jogadores mais fortes falham menos; o cansaço aumenta o erro (até +35%) */
const execQ=p=>clamp(1.3-(p.rating||65)/150,.7,1)*(PREF.fatigue===false?1:1+(1-(p.stam==null?1:p.stam))*.35);
function kick(p,tx,ty,spd,noise,lift,spin){
  noise=(noise||0)*execQ(p);
  const b=G.ball,a=Math.atan2(ty-b.y,tx-b.x)+rnd(-(noise||0),noise||0);
  p.kx=b.x;p.ky=b.y;p.kz=b.z||0;p.kt0=G.t;      // onde a bola estava quando foi chutada (a animação do pé vai até lá)
  b.owner=null;b.kt=0;b.vx=Math.cos(a)*spd;b.vy=Math.sin(a)*spd;b.lastTeam=p.team;b.last=p;p.kickCd=.28;p.kickAnim=.65;
  b.vz=lift>0?lift:0;b.z=lift>0?2:0;b.sp=spin||0;       // lift: velocidade vertical de saída; spin: efeito lateral (+ curva para a direita da trajetória)
  sfx("kick",spd);if(spd>9.6)ring(b.x,b.y,"#ffffff");
}
/* ponto de interceção: onde o colega estará quando a bola chegar (a bola perde velocidade a ritmo constante) */
function leadPoint(p,q,v0,extra){
  let tx=q.x,ty=q.y;
  for(let i=0;i<4;i++){
    const d=Math.hypot(tx-p.x,ty-p.y),r=Math.min(.96,d*.022/v0),n=r>0?Math.log(1-r)/Math.log(.978):0;
    tx=q.x+q.vx*n*.9+(extra?extra.x:0);ty=q.y+q.vy*n*.9+(extra?extra.y:0);
  }
  return{x:clamp(tx,X0+8,X1-8),y:clamp(ty,Y0+8,Y1-8)};
}
/* tempo (em imagens) que a bola demora a percorrer d com a velocidade inicial v0 (a bola perde velocidade a ritmo constante) */
function flightSteps(d,v0){const r=Math.min(.96,d*.022/v0);return r>0?Math.log(1-r)/Math.log(.978):0}
function passTo(p,q,noiseMult,maxSpd,boost){
  if(!q)return;
  const bo=boost||1,d0=dist(p,q),v0=clamp((3.5+d0*.022)*bo,4.4,maxSpd||9.8),L=leadPoint(p,q,v0),d=Math.hypot(L.x-p.x,L.y-p.y);
  const vp=clamp((3.5+d*.022)*bo,4.4,maxSpd||9.8),lob=d>300?Math.min(3.4,GRAV*flightSteps(d,vp)/2*.92):0;      // passe longo: bola no ar, aterra junto ao colega
  kick(p,L.x,L.y,vp,(.008+d/18000)*(noiseMult||1),lob,rnd(-.25,.25)*(lob?1:0));
  G.ball.pend={type:"pass",team:p.team,from:p,to:q};G.stats[p.team].passA++;
}
function cross(p,team){
  const gx=sd(team)===0?X1-105:X0+105,tx=gx+rnd(-25,25),ty=H/2+rnd(-70,70);
  const recv=nearestOf(team,{x:tx,y:ty},false,p);
  const dc=Math.hypot(tx-p.x,ty-p.y),vc=clamp(3.6+dc*.021,6,10.5);
  kick(p,tx,ty,vc,.04,Math.min(3.2,GRAV*flightSteps(dc,vc)/2*.9),rnd(-.45,.45));      // cruzamento: bola alta com algum efeito
  G.ball.pend={type:"pass",team,from:p,to:recv};G.stats[team].passA++;
}
function shoot(p,c,iy,nm){
  nm=nm||1;
  crowdEvent("shot");
  const gx=sd(p.team)===0?X1+6:X0-6;
  const ty=(Math.abs(iy)>.2?H/2+iy*(GH/2-14):H/2+(p.y<H/2?1:-1)*rnd(12,52))+(nm!==1?rnd(-10,10)*(nm-.45):0);
  const d=Math.abs(gx-p.x);
  const vs=PREF.shotStyle==="placed"?7+c*4:7.5+c*7.5,placed=PREF.shotStyle==="placed";
  const elev=Math.max(0,.02+c*.055+(c>.8&&!placed?rnd(-.03,.075):rnd(-.02,.03)));      // tangente do ângulo de saída
  kick(p,gx,ty,vs,((placed?.012:.025)+(1-c)*.04+d/9000)*nm,vs*elev,rnd(-1,1)*.5*(.3+c));
  G.ball.pend={type:"shot",team:p.team};G.stats[p.team].shots++;
  if(c>.85){G.hot=1.6;burst("spark",G.ball.x,G.ball.y,16,["#ffb020","#ff5a1f","#ffffff"],4,.45,3);if(!PREF.reduceFx)G.shake=Math.max(G.shake,.15)}
}
function aiShoot(p,D){
  crowdEvent("shot");
  const gx=sd(p.team)===0?X1+6:X0-6,d=Math.hypot(gx-p.x,H/2-p.y);
  const va=rnd(10,13.5);
  kick(p,gx,rnd(GY0+14,GY1-14),va,(.035+d/9000)*D.noise,va*Math.max(0,.02+rnd(-.02,.07)),rnd(-.5,.5));
  G.ball.pend={type:"shot",team:p.team};G.stats[p.team].shots++;
}
/* Estatísticas: cada passe/remate fica pendente até ser resolvido uma única vez */
function onGain(q){
  const b=G.ball,pd=b.pend;
  if(pd){
    if(pd.type==="pass"){if(q.team===pd.team&&q!==pd.from){G.stats[pd.team].passC++;if(G.tut)G.tut.passOK=true}}
    else if(pd.type==="shot"&&q.role==="GK"&&q.team!==pd.team){G.stats[pd.team].onT++;G.stats[q.team].saves++;crowdEvent("save")}
    b.pend=null;
  }
  b.lastTeam=q.team;b.last=q;
}
function onDeflectGK(gk){const b=G.ball,pd=b.pend;if(pd&&pd.type==="shot"&&gk.team!==pd.team){G.stats[pd.team].onT++;G.stats[gk.team].saves++;crowdEvent("save")}b.pend=null;b.lastTeam=gk.team;b.last=gk}

function ballPhysics(live){
  const b=G.ball,classic=!G.tut;
  if(b.owner){
    const o=b.owner,sp=Math.hypot(o.vx,o.vy),off=(10+(sp>.6?3.6*(.5+.5*Math.sin(o.run*1.15)):0))*(o.dribble?.75:1);
    b.z=0;b.vz=0;b.sp=0;
    if(live&&o.role!=="GK"&&!o.dribble&&o.sprinting&&o.turnAcc>1.5&&sp>.75*o.sp&&Math.random()<.03){      // viragem brusca em sprint: o toque sai mais comprido e a bola fica solta
      o.turnAcc=0;b.owner=null;b.kt=0;b.vx=o.vx*1.35;b.vy=o.vy*1.35;o.kickCd=.22;b.lastTeam=o.team;b.last=o;return}
    b.x+=(o.x+o.fx*off-b.x)*.6;b.y+=(o.y+o.fy*off-b.y)*.6;b.vx=o.vx;b.vy=o.vy;
    const inM=b.y>GY0+4&&b.y<GY1-4;
    if(live&&o.role!=="GK"&&inM&&(b.x<X0-3||b.x>X1+3)){b.owner=null;goal(sd(b.x<X0?1:0));return}
    if(live&&classic&&o.role!=="GK"&&(b.y<Y0-3||b.y>Y1+3||((b.x<X0-3||b.x>X1+3)&&!inM))){b.lastTeam=o.team;b.owner=null;ballOut();return}
    b.x=clamp(b.x,X0+3,X1-3);b.y=clamp(b.y,Y0+3,Y1-3);return;
  }
  const pd0=b.pend;
  if(pd0&&pd0.type==="pass"&&pd0.to&&pd0.team===0&&PREF.passAssist!=="manual"&&!pd0.to.off){const sp1=Math.hypot(b.vx,b.vy);if(sp1>1.5){const a1=Math.atan2(b.vy,b.vx),ta=Math.atan2(pd0.to.y+pd0.to.vy*3-b.y,pd0.to.x+pd0.to.vx*3-b.x);let da=Math.atan2(Math.sin(ta-a1),Math.cos(ta-a1));da=clamp(da,-.03,.03);const na=a1+da;b.vx=Math.cos(na)*sp1;b.vy=Math.sin(na)*sp1}}
  b.kt=(b.kt||0)+1;
  const air=b.z>.3||b.vz>.05,px=b.x,py=b.y;
  if(air){
    if(b.sp){const k=b.sp*.011,ax=-b.vy*k,ay=b.vx*k;b.vx+=ax;b.vy+=ay;b.sp*=.992}       // efeito: curva perpendicular à velocidade
    b.vz-=GRAV;b.z+=b.vz;
  }
  b.x+=b.vx;b.y+=b.vy;const dr=air?.982:.978;b.vx*=dr;b.vy*=dr;
  if(b.z<=0&&(air||b.vz<0)){                                                    // chão: ressalto com perda de energia e atrito
    b.z=0;
    if(b.vz<-.9){b.vz=-b.vz*.56;b.vx*=.92;b.vy*=.92;if(b.sp){const sv=Math.hypot(b.vx,b.vy)||1;b.vx+=-b.vy/sv*b.sp*.7;b.vy+=b.vx/sv*b.sp*.7;b.sp*=.5}}else{b.vz=0;b.sp*=.8}
  }
  if(Math.hypot(b.vx,b.vy)<.04&&b.z<=0)b.vx=b.vy=0;
  if(live&&!b.inNet)goalFrame(px,py);
  const inNet=b.x<X0||b.x>X1;
  if(!inNet){
    if(classic&&live){if(b.y<Y0-4||b.y>Y1+4){ballOut();return}}
    else{if(b.y<Y0+5){b.y=Y0+5;b.vy=Math.abs(b.vy)*.6}if(b.y>Y1-5){b.y=Y1-5;b.vy=-Math.abs(b.vy)*.6}}
  }
  const inM=b.y>GY0+4&&b.y<GY1-4&&b.z<BAR_H-1.5;      // por cima da barra não é golo
  for(const side of [0,1]){
    const beyond=side===0?X0-b.x:b.x-X1;
    if(beyond<=-5)continue;
    if(inM||b.inNet){if(beyond>0)b.inNet=true;if(beyond>3&&live&&G.state==="play"){goal(sd(side===0?1:0));return}}
    else if(classic&&live){if(beyond>4){ballOut();return}}
    else{b.x=side?X1-5:X0+5;b.vx=side?-Math.abs(b.vx)*.6:Math.abs(b.vx)*.6}
  }
  if(b.x>=X0&&b.x<=X1)b.inNet=false;
  if(b.inNet&&(b.x<X0||b.x>X1)){if(b.z>BAR_H-3){b.z=BAR_H-3;b.vz=-Math.abs(b.vz)*.3}b.y=clamp(b.y,GY0+5,GY1-5);if(b.x<X0-24){b.x=X0-24;b.vx=Math.abs(b.vx)*.15}if(b.x>X1+24){b.x=X1+24;b.vx=-Math.abs(b.vx)*.15}}
  if(!live)return;
  let best=null,bd=1e9;
  for(const p of G.players){if(p.off||p.wall||p.kickCd>0||p.stun>0)continue;const gk=p.role==="GK",reach=gk?(p.dive||p.gkJump>0?46:34):27;if(b.z>reach)continue;const r=gk?(p.dive?25:17):13,d=Math.hypot(p.x-b.x,p.y-b.y);if(d<r&&d<bd){bd=d;best=p}}
  const d_gk=best?Math.hypot(best.x-b.x,best.y-b.y):0;
  if(!best)return;
  if(best.role!=="GK"&&b.z>7){best.kickCd=.18;b.vx*=.5;b.vy*=.5;b.vz=Math.min(b.vz,0)*.3;return}      // bola aérea: amortece mas não fica presa ao pé
  const s=Math.hypot(b.vx,b.vy);
  if(best.role==="GK"){
    if(best.dive&&b.pend&&b.pend.pen&&Math.random()<.4){best.kickCd=.35;return}
    let ok=true;
    const sk=gkSkill(best),close=1-Math.min(1,d_gk/(best.dive?23:17));      // proximidade da bola ao corpo do guarda-redes no contacto
    if(s>5){ok=Math.random()<clamp((1-(s-5)*.08+(best.dive?.08:0)-(b.z>20?.1:0)-(1-close)*.18)*(.9+.1*sk),.2,.93)*Math.min(1.1,sk)}
    /* bola muito forte, esticada ou alta: em vez de agarrar, defende para o lado/para cima (ressalto controlado) */
    if(ok&&(s>9||close<.35||b.z>20)&&Math.random()<(best.dive?.6:.35)){onDeflectGK(best);const sg=best.dive?best.dive.side:(b.y>=best.y?1:-1);b.vx=-b.vx*.3;b.vy=sg*rnd(1.2,4.2);if(b.z>14)b.vz=Math.max(b.vz,1.4);best.kickCd=.45;sfx("kick",6);burst("spark",b.x,b.y,10,["#ffffff","#cfe8ff"],3.2,.3,2.5);return}
    if(!ok&&s>8&&Math.random()<clamp((s-8)*.11,0,.5)){b.vx*=.6;b.vy*=.6;best.kickCd=.45;sfx("kick",4);return}      // roça na bola e amortece-a, mas não a segura: pode entrar
    if(!ok){onDeflectGK(best);b.vx=-b.vx*.45+rnd(-1.5,1.5);b.vy=b.vy*.6+rnd(-3,3);best.kickCd=.45;sfx("kick",5);burst("spark",b.x,b.y,12,["#ffffff","#cfe8ff"],3.5,.3,2.5);return}
    if(s>5){ring(b.x,b.y,"#f2b705");if(!best.dive&&!(best.gkJump>0))best.gkJump=.6}
  }else if(s>8.5){
    // passes tensos e remates difíceis de dominar: melhor atributo amortece melhor; bola no ar piora; fadiga piora
    let acc=clamp(.34+((best.rating||65)-60)/110-(b.z>6?.12:0)-(PREF.fatigue===false?0:(1-(best.stam==null?1:best.stam))*.12),.15,.85);
    if(G.o.diff==="easy"&&best.team===0)acc=Math.max(acc,.82);
    if(Math.random()>=acc){best.kickCd=.2;return}
  }
  if(typeof checkOffside==="function"&&checkOffside(best))return;
  const inc=s;onGain(best);b.owner=best;best.kickCd=0;
  if(inc>3.5&&best.role!=="GK"){const k=inc>7?.6:.8;best.vx*=k;best.vy*=k}
  if(best.role==="GK"){best.gkHold=.7;b.vx=b.vy=0;best.fx=sd(best.team)===0?1:-1;best.fy=0}
}
/* postes e barra: segmento da bola entre duas imagens a cruzar a linha de baliza */
function goalFrame(px,py){
  const b=G.ball;
  for(const gl of [X0,X1]){
    if((px-gl)*(b.x-gl)>=0)continue;
    const t=(gl-px)/((b.x-px)||1e-6),yc=py+(b.y-py)*t,zc=b.z-b.vz*(1-t),dir=Math.sign(px-gl)||1;
    let hit=null;
    for(const post of [GY0,GY1])if(Math.abs(yc-post)<POST_R&&zc<BAR_H+POST_R)hit={post};
    if(hit){b.x=gl+dir*1.5;b.y=py;b.vx=-b.vx*.62;b.vy=(b.vy*.5)+(yc>hit.post?1:-1)*Math.abs(b.vx)*.3;b.vz*=.7;b.sp*=.5;sfx("post");if(b.pend&&b.pend.type==="shot")b.pend.hitPost=true;return}
    if(yc>GY0&&yc<GY1&&Math.abs(zc-BAR_H)<POST_R){b.x=gl+dir*1.5;b.vx=-b.vx*.55;b.vz=(zc>=BAR_H?.9:-.5)*Math.max(1,Math.abs(b.vz))*.6;b.z=zc>=BAR_H?BAR_H+POST_R+.2:BAR_H-POST_R-.2;sfx("post");if(b.pend&&b.pend.type==="shot")b.pend.hitPost=true;return}
  }
}
/* probabilidade de um desarme: distância, orientação do desarmador, velocidade relativa, momento (janela a meio do movimento), diferença de qualidade e fôlego */
function tackleChance(q,o,dq,tk){
  const sl=tk&&q.tkSlide,reach=sl?28:tk?22:17;
  const ux=(o.x-q.x)/(dq||1),uy=(o.y-q.y)/(dq||1),al=clamp(q.fx*ux+q.fy*uy,-1,1);      // 1 = de frente para o portador
  const rel=Math.hypot(q.vx-o.vx,q.vy-o.vy)/Math.max(1,o.sp);
  const tm=tk?clamp(1.05-Math.abs(1-q.dash/(q.tkDur||.2)-.5)*1.1,.45,1):1;      // melhor a meio do movimento
  let c=(sl?.74:tk?.62:.1)*(.4+.6*Math.max(0,al))*(1.12-dq/reach*.45)*tm*(1-clamp(rel-.8,0,1.2)*.22);
  c*=clamp(q.rating/o.rating,.75,1.25)*(.9+.1*(q.stam==null?1:q.stam))*(o.dribble?.85:1);
  return clamp(c,0,.92);
}
function tackles(){
  const b=G.ball,o=b.owner;if(!o||o.role==="GK")return;
  G.tk=G.tk||{try:0,win:0,foul:0,miss:0,loose:0};
  for(const q of G.players){
    if(q.off||q.team===o.team||q.stun>0||q.role==="GK")continue;
    const human0=q===G.ctrl&&!G.auto,dq=dist(q,o),tk=!!q.tackling,reach=tk?(q.tkSlide?28:22):(human0?15:22);
    if(dq>reach)continue;
    const human=q===G.ctrl&&!G.auto;
    const ux=(o.x-q.x)/(dq||1),uy=(o.y-q.y)/(dq||1),al=clamp(q.fx*ux+q.fy*uy,-1,1),rel=Math.hypot(q.vx-o.vx,q.vy-o.vy)/Math.max(1,o.sp),behind=(q.x-o.x)*o.fx+(q.y-o.y)*o.fy<-6;
    const cs=(q.vx-o.vx)*ux+(q.vy-o.vy)*uy;      // velocidade de aproximação ao portador
    const info={slide:tk&&!!q.tkSlide,rel,behind,al};
    /* choque violento sem tentativa de jogar a bola (carga por trás ou de lado a grande velocidade) é falta */
    if(!tk&&!G.tut&&G.state==="play"&&!(q.foulCd>0)&&cs>2.7&&(behind||al<.4)){G.tk.foul++;callFoul(q,o,false,info);break}
    let ch;
    if(tk){                     // desarme ativo: uma só tentativa por movimento, no primeiro contacto
      if(q.tkRoll)continue;
      q.tkRoll=true;ch=tackleChance(q,o,dq,true);G.tk.try++;
    }else if(human)ch=Math.hypot(q.vx,q.vy)>.5?.035*(.5+.5*Math.max(0,q.fx*(o.x-q.x)/(dq||1)+q.fy*(o.y-q.y)/(dq||1))):0;
    else if(G.tut)ch=0;
    else{const D=q.team===1?G.D:MATE;ch=.028*D.tackle*(q.rating/o.rating)*(.6+.4*Math.max(0,q.fx*(o.x-q.x)/(dq||1)+q.fy*(o.y-q.y)/(dq||1)));if(o===G.ctrl)ch*=.85}
    if(Math.random()<ch){
      /* ganhou a bola, mas é falta se entrou por trás ou com um carrinho descoordenado (de lado ou a grande velocidade) */
      const reck=info.slide&&(al<.3||rel>1.6);
      if(!G.tut&&!(q.foulCd>0)&&((behind&&(tk||cs>1))||reck)){G.tk.foul++;callFoul(q,o,info.slide&&(behind||rel>1.6),info);break}
      if(info.slide&&!G.tut)G.varNote={type:"foul",team:q.team,player:q,victim:o,x:o.x,y:o.y,t:G.t,reck:al<.5||rel>1.2};
      G.tk.win++;onGain(q);b.owner=q;o.stun=.5;o.kickCd=.4;q.tackling=false;q.dash=0;q.kickCd=0;
      if(q===G.ctrl)G.needRelease=true;
      sfx("tackle");burst("dust",o.x,o.y,12,["#cdbb8f","#8fbf6a","#e8dcc0"],2.2,.55,3);break;
    }else if(tk){
      /* desarme falhado: o portador mantém a bola; um carrinho a grande velocidade que lhe acerta pode soltá-la, e entradas por trás ou muito descoordenadas são falta */
      if(info.slide&&!G.tut&&!(q.foulCd>0)&&(behind||al<.3||rel>1.6)){G.tk.foul++;callFoul(q,o,behind||rel>1.6,info);break}      // carrinho falhado com contacto
      if(info.slide&&rel>1.1){
        const ux=(o.x-q.x)/(dq||1),uy=(o.y-q.y)/(dq||1);b.owner=null;b.vx=ux*3.2+q.vx*.3;b.vy=uy*3.2+q.vy*.3;b.pend=null;o.kickCd=.35;o.stun=.2;G.tk.loose++;
        sfx("tackle");break;
      }
    }
  }
}
function goal(t){
  crowdEvent("goal");
  const b=G.ball;b.owner=null;
  if(G.tut){if(G.tut.goalAny){b.vx*=.5;b.vy*=.5;return}G.tut.goalAny=true;if(t===0&&tutStepDef(G.tut.step).goalStep)G.tut.goal=true;else G.tut.retry=0;b.pend=null;sfx("goal");confetti(0,PREF.reduceFx?30:90);return}
  if(b.pend&&b.pend.type==="shot"&&b.pend.team===t)G.stats[t].onT++;
  b.pend=null;
  G.score[t]++;G.events.push({min:minute(),team:t});
  G.state="goal";G.st=PREF.reduceFx?1.6:2.4;G.goalRec=0;G.nextKick=1-t;
  G.msg="GOLO!";G.msgSub=G.teams[t].n;G.charging=false;G.charge=0;G.setp=null;
  sfx("goal");goalFx(t);
  if(!PREF.reduceFx){G.flash=.45;G.shake=.4;G.slow=.9;G.flashT=2.4}
  G.net={x:sd(t)===0?X1:X0,dir:sd(t)===0?1:-1,y:clamp(b.y,GY0+12,GY1-12),amp:1};
}

/* ---------- Modo Clássico: reposições ---------- */
function ballOut(){
  const b=G.ball;b.pend=null;const lt=b.lastTeam;
  if(b.y<Y0||b.y>Y1){startSetPiece("throw",1-lt,clamp(b.x,X0+24,X1-24),b.y<Y0?Y0:Y1);return}
  const side=b.x<X0?0:1;
  const def=sd(side);
  if(lt===def)startSetPiece("corner",1-def,side===0?X0:X1,b.y<H/2?Y0:Y1);
  else startSetPiece("goalkick",def,side===0?X0+48:X1-48,H/2+(b.y<H/2?-45:45));
}
function startSetPiece(kind,team,x,y){
  const b=G.ball;b.owner=null;b.vx=b.vy=0;b.x=x;b.y=y;b.pend=null;
  G.state="setpiece";G.charging=false;G.charge=0;G.trail.length=0;G.hot=0;
  G.msg={throw:"Lançamento lateral",corner:"Canto",goalkick:"Pontapé de baliza",freekick:"Livre"}[kind];G.msgSub=G.teams[team].n;
  const taker=kind==="goalkick"?G.players.find(p=>p.team===team&&p.role==="GK"):nearestOf(team,{x,y},false);
  let fx,fy;
  if(kind==="throw"){fx=0;fy=y<H/2?1:-1}
  else if(kind==="corner"){const ax=(x<W/2?X0+110:X1-110)-x,ay=H/2-y,d=Math.hypot(ax,ay);fx=ax/d;fy=ay/d}
  else{fx=sd(team)===0?1:-1;fy=0}
  taker.fx=fx;taker.fy=fy;taker.x=clamp(x-fx*11,X0+6,X1-6);taker.y=clamp(y-fy*11,Y0+6,Y1-6);taker.vx=taker.vy=0;
  b.owner=taker;b.lastTeam=team;b.last=taker;
  G.setp={kind,team,x,y,t:0,taker,tx:taker.x,ty:taker.y};
  for(const q of G.players){if(q.off||q.team===team)continue;const d=dist(q,b);if(d<70){const a=Math.atan2(q.y-b.y,q.x-b.x)||0;q.x=clamp(b.x+Math.cos(a)*72,X0+6,X1-6);q.y=clamp(b.y+Math.sin(a)*72,Y0+6,Y1-6)}}
  if(team===0&&(taker.role!=="GK"||kind==="goalkick"))setCtrl(taker);
  sfx("whistle");teamBrain(0);teamBrain(1);
}
function stepSetPiece(){
  const sp=G.setp,tk=sp.taker,b=G.ball;sp.t+=DT;
  for(const p of G.players){if(p.off)continue;p.kickCd-=DT;p.think-=DT;if(p.gkJump>0)p.gkJump-=DT;if(p.gkDown>0){p.gkDown-=DT*2;if(p.dive)p.dive.t+=DT*2;if(p.gkDown<=0)p.dive=null}}
  brains();
  const human=sp.team===0&&tk===G.ctrl;
  for(const p of G.players){
    if(p.off)continue;
    if(p===tk){p.dx=p.dy=0;continue}
    if(p===G.ctrl&&!human){p.sprint=false;ai(p);continue}
    ai(p);
  }
  movePlayers();separate();
  tk.x=sp.tx;tk.y=sp.ty;tk.vx=tk.vy=0;
  if(human){
    let ix=input.x,iy=input.y;const m=Math.hypot(ix,iy);
    if(m>.3){ix/=m;iy/=m;const inX=sp.kind==="throw"?0:(sp.x<W/2?1:-1),inY=sp.y<H/2?1:-1;
      if(sp.kind==="throw"&&iy*inY<.15)iy=.15*inY;
      if(sp.kind==="corner"){if(ix*inX<.1)ix=.1*inX;if(iy*inY<.1)iy=.1*inY}
      const d=Math.hypot(ix,iy);tk.fx=ix/d;tk.fy=iy/d;G.aim={x:tk.fx,y:tk.fy}}else G.aim=null;
    if(--G.tickPT<=0){G.tickPT=3;G.passTarget=choosePassTarget(tk)}
  }
  for(const q of G.players){if(q.off||q.team===sp.team)continue;const d=dist(q,b);if(d<70&&d>0){q.x=b.x+(q.x-b.x)/d*70;q.y=b.y+(q.y-b.y)/d*70}}
  ballPhysics(false);
  let go=false;
  if(human){
    if(sp.t>.45&&(input.passPressed||input.shootPressed)){
      if(sp.kind==="freekick"&&input.shootPressed)shoot(tk,.65,input.y);
      else if(sp.kind==="corner"&&input.shootPressed)cross(tk,0);
      else if(sp.kind==="goalkick"&&input.shootPressed){let best=null,bs=-1e9;for(const q of G.players){if(q.off||q.team!==tk.team||q===tk||q.role==="GK")continue;const al=G.aim?((q.x-tk.x)*G.aim.x+(q.y-tk.y)*G.aim.y)/Math.max(1,dist(tk,q)):0,s=nxOf(tk.team,q.x)*3+al*2+(laneClear(tk,q,16)?1:0);if(s>bs){bs=s;best=q}}passTo(tk,best||choosePassTarget(tk),1.2,10.5)}
      else passTo(tk,G.passTarget||choosePassTarget(tk),.6,sp.kind==="throw"?7.5:9.5);
      go=true;
    }else if(sp.t>7){passTo(tk,choosePassTarget(tk),.6,7.5);go=true}
  }else if(sp.t>1.0){
    if(sp.kind==="freekick"&&Math.abs((sd(sp.team)===0?X1:X0)-tk.x)<280)aiShoot(tk,G.D);
    else if(sp.kind==="goalkick")gkDistribute(tk);
    else if(sp.kind==="corner"&&Math.random()<.75)cross(tk,sp.team);
    else{const st=sp.team===1?STYLES[G.styleR]:STYLES.posse;const q=bestPassTarget(tk,st)||nearestOf(sp.team,tk,false,tk);passTo(tk,q&&(q.p||q),1,sp.kind==="throw"?7.5:9.5)}
    go=true;
  }
  if(go){G.state="play";G.setp=null;G.msg="";G.passTarget=null}
}

/* ================= Inteligência artificial ================= */
const CAND=[[0,0],[.06,0],[-.05,0],[0,.08],[0,-.08],[.05,.07],[.05,-.07]];
function wouldBeOffside(p,q){if(PREF.offsideVar===false||(G.tut&&!G.tut.allowOff))return false;const sk=G.setp&&G.setp.kind;if(sk==="throw"||sk==="goalkick"||sk==="corner")return false;const s=sd(p.team)===0?1:-1;let a=-1e9,b2=-1e9;for(const o of G.players){if(o.off||o.team===p.team)continue;const v=s*o.x;if(v>a){b2=a;a=v}else if(v>b2)b2=v}return s*q.x>Math.max(s*W/2,s*p.x,b2)+4}
function deepestDef(t){let m=0;for(const q of G.players){if(q.off||q.team===t||q.role==="GK")continue;m=Math.max(m,nxOf(t,q.x))}return m}
/* ponto de apoio curto à volta do portador: livre de adversários, com linha de passe limpa, perto de quem o vai ocupar e longe de outros apoios */
function offerPoint(t,o,p,taken){
  const f=Math.atan2(o.fy,o.fx);let best=null,bs=-1e9;
  for(const da of [-2.0,-1.2,1.2,2.0,3.14]){
    const a=f+da,r=80,pt={x:clamp(o.x+Math.cos(a)*r,X0+20,X1-20),y:clamp(o.y+Math.sin(a)*r,Y0+20,Y1-20)};
    let md=1e9;for(const q of G.players)if(!q.off&&q.team!==t)md=Math.min(md,Math.hypot(q.x-pt.x,q.y-pt.y));
    let sc=Math.min(md,120)+(laneClear(o,pt,16)?80:-90)-dist(p,pt)*.18+(Math.abs(da)>3?-15:0);
    for(const tk of taken)sc-=Math.max(0,60-Math.hypot(tk.x-pt.x,tk.y-pt.y))*1.5;
    if(sc>bs){bs=sc;best=pt}
  }
  return best;
}
/* afasta alvos demasiado próximos entre colegas (evita que vários corram para o mesmo ponto) */
function spreadTargets(field,t){
  const act=field.filter(p=>p.job!=="press"&&p.job!=="offer"&&p.job!=="mark"&&!(t===0&&p===G.ctrl));
  for(let pass=0;pass<3;pass++)for(let i=0;i<act.length;i++)for(let j=i+1;j<act.length;j++){
    const a=act[i],c=act[j],d=Math.hypot(pxOf(t,a.bx)-pxOf(t,c.bx),pyOf(a.by)-pyOf(c.by));
    if(d<38){const push=(38-d)/(Y1-Y0)*.5+.012,sg=a.by===c.by?(i%2?1:-1):(a.by<c.by?-1:1);a.by=clamp(a.by+sg*push,.06,.94);c.by=clamp(c.by-sg*push,.06,.94)}
  }
}
/* linha defensiva coordenada: os defesas partilham a profundidade, sobem e descem juntos (no máx. ~0,05 do campo por segundo) e ficam do lado da baliza do atacante mais adiantado */
function coordLine(field,opps,t){
  const ds=field.filter(p=>p.role==="D"&&(p.job==="hold"||p.job==="support"));
  if(!ds.length)return;
  const tgt=ds.reduce((a,p)=>a+p.bx,0)/ds.length;
  let cap=1;const deep=Math.min(1,...opps.filter(q=>q.role!=="GK").map(q=>nxOf(t,q.x)));if(deep<.55)cap=Math.max(.08,deep-.02);
  G.dline=G.dline||[tgt,tgt];
  G.dline[t]+=clamp(Math.min(tgt,cap)-G.dline[t],-.014,.014);
  for(const p of ds)p.bx=clamp(G.dline[t]+(p.bx-tgt)*.5,.06,.62);
}
function teamBrain(t){
  const b=G.ball,o=b.owner,our=!!(o&&o.team===t),D=t===1?G.D:MATE;
  const st=t===1?STYLES[G.styleR]:STYLES.posse,tac=t===0?TACTICS[G.o.tac]||TACTICS.bal:TACTICS.bal;
  const line=st.line+tac.line,bn=nxOf(t,b.x),byn=(b.y-Y0)/(Y1-Y0);
  const field=G.players.filter(p=>p.team===t&&!p.off&&p.role!=="GK"),opps=G.players.filter(p=>p.team!==t&&!p.off);
  for(const p of field){
    let tx=p.hx+(bn-.5)*.48+line+(our?.12+tac.support:-.05);
    tx=clamp(tx,.07,{D:.62,M:.82,F:.92}[p.role]);
    if(!our&&p.role==="D")tx=Math.min(tx,Math.max(.1,bn-.06));
    p.bx=tx;p.by=clamp(p.hy+(byn-.5)*.38,.06,.94);p.job="hold";
  }
  if(our){
    const dl=deepestDef(t);
    for(const p of field){
      if(p===o)continue;
      if(p.role==="F"&&bn>.28&&(st.counter>.5||Math.random()<.4+tac.support*3)){p.bx=clamp(Math.min(Math.max(p.bx,dl-.03),dl-(Math.random()<.14?.004:.012)),.1,.93);p.job="run"}      // corre até à linha, sem a passar (nunca em fora de jogo)
      let best=[p.bx,p.by],bs=-1e9;
      for(const [ox,oy] of CAND){
        const nx=clamp(p.bx+ox,.06,.93),ny=clamp(p.by+oy,.06,.94),pt={x:pxOf(t,nx),y:pyOf(ny)};
        let md=1e9;for(const q of opps)md=Math.min(md,Math.hypot(q.x-pt.x,q.y-pt.y));
        const s=Math.min(md,130)-Math.hypot(ox,oy)*260+(o&&laneClear(o,pt,22)?45:0)+ox*90*(.5+st.risk);
        if(s>bs){bs=s;best=[nx,ny]}
      }
      p.bx=best[0];p.by=best[1];if(p.job!=="run")p.job="support";
    }
    /* ninguém espera em posição de fora de jogo à frente da última linha (só conta quando há fora de jogo) */
    if(PREF.offsideVar!==false&&!G.tut)for(const p of field)if(p!==o&&p.bx>dl-.006)p.bx=dl-.006;
    /* portador pressionado: os dois colegas mais próximos oferecem linha de passe curta */
    if(o&&o.role!=="GK"&&bn<.5&&minOppDist(o)<90){      // antes de a pressão chegar: os colegas mais próximos (até 260 u) aproximam-se; no último terço só um, para o ataque não perder gente
      const cand=field.filter(p=>p!==o&&p.job!=="run"&&dist(p,o)<260).sort((a,c)=>dist(a,o)-dist(c,o)).slice(0,2),taken=[];
      for(const p of cand){const pt=offerPoint(t,o,p,taken);if(pt){taken.push(pt);p.bx=clamp(nxOf(t,pt.x),.06,.93);p.by=clamp((pt.y-Y0)/(Y1-Y0),.06,.94);p.job="offer"}}
    }else if(o&&o.role!=="GK"&&bn>.3&&bn<.85){
      /* com tempo: um médio ou avançado desmarca-se nas costas da defesa, pelo corredor mais livre, sempre do lado de dentro da linha de fora de jogo; um corredor de cada vez */
      G.runT=G.runT||[0,0];
      if(!(G.runT[t]>G.t)){
        const cands=field.filter(p=>p!==o&&(p.job==="support"||p.job==="hold")&&nxOf(t,p.x)>.3).sort((a,c)=>nxOf(t,c.x)-nxOf(t,a.x));
        const p=cands[0];
        if(p){
          let bestY=p.by,bd=-1;
          for(const dy of [-.22,0,.22]){const ny=clamp(p.by+dy,.1,.9),px=pxOf(t,dl-.01),py=pyOf(ny);let md=1e9;for(const q of opps)md=Math.min(md,Math.hypot(q.x-px,q.y-py));if(md>bd){bd=md;bestY=ny}}
          p.bx=clamp(dl-.01,.1,.93);p.by=bestY;p.job="run";G.runT[t]=G.t+2.4;
        }
      }
    }
  }else{
    const pred=predictBall(D.antic);
    const sorted=field.slice().sort((a,c)=>Math.hypot(a.x-pred.x,a.y-pred.y)-Math.hypot(c.x-pred.x,c.y-pred.y));
    const nPress=Math.max(1,st.press+(t===0?tac.press:0)),pdist=st.pdist+(t===0?tac.pdist:0);
    const used=new Set();let k=0;
    for(const p of sorted){
      if(k>=nPress)break;
      if(t===0&&p===G.ctrl){used.add(p);k++;continue}
      if(k>0&&Math.hypot(p.x-b.x,p.y-b.y)>pdist)break;
      p.job="press";used.add(p);k++;
    }
    if(t===0&&!used.has(G.ctrl)&&G.ctrl)used.add(G.ctrl);
    if(o){const cover=sorted.find(p=>!used.has(p));if(cover){cover.job="cover";used.add(cover)}}
    const free=opps.filter(q=>q!==o&&q.role!=="GK");
    for(const p of sorted){
      if(used.has(p))continue;
      let best=null,bd=1e9;const hx=pxOf(t,p.bx),hy=pyOf(p.by);
      for(const q of free){const d=Math.hypot(q.x-hx,q.y-hy);if(d<bd){bd=d;best=q}}
      if(best&&bd<170){
        free.splice(free.indexOf(best),1);
        const gx=sd(t)===0?X0:X1,mx=best.x+(gx-best.x)*.16,my=best.y+(H/2-best.y)*.1;
        const w=.55+(t===0&&G.o.tac==="def"?.2:0);
        p.bx=clamp(nxOf(t,mx)*w+p.bx*(1-w),.05,.9);p.by=clamp(((my-Y0)/(Y1-Y0))*w+p.by*(1-w),.05,.95);p.job="mark";
      }
    }
    /* os defesas não abandonam todos a posição: só o mais próximo da bola sai a pressionar ou a fazer cobertura */
    const dj=field.filter(p=>p.role==="D"&&(p.job==="press"||p.job==="cover")&&!(t===0&&p===G.ctrl)).sort((a,c)=>Math.hypot(a.x-b.x,a.y-b.y)-Math.hypot(c.x-b.x,c.y-b.y));
    for(let i=1;i<dj.length;i++)dj[i].job="hold";
  }
  coordLine(field,opps,t);
  spreadTargets(field,t);
}
function ai(p){
  const b=G.ball,o=b.owner;
  if(p.stun>0){p.dx=p.dy=0;p.sprint=false;return}
  if(G.tut&&tutAI(p))return;
  if(p.role==="GK")return aiGK(p);
  if(o===p)return aiCarrier(p);
  const D=p.team===1?G.D:MATE,st=p.team===1?STYLES[G.styleR]:STYLES.posse;
  p.sprint=false;
  if(!o&&b.pend&&b.pend.type==="pass"&&b.pend.to===p){const t=predictBall(6);return seek(p,t.x,t.y,1)}
  if(p.job==="press"){
    const t=o?predictBall(3):predictBall(D.antic),d=Math.hypot(t.x-p.x,t.y-p.y);
    p.sprint=p.energy>.4&&(d<90||(st.press>1&&d<220)||!o);
    return seek(p,t.x,t.y,p.energy<.2||(p.stam!=null&&p.stam<.5)?.88:1);      // sem fôlego a pressão é menos intensa
  }
  if(p.job==="offer"){const tx=pxOf(p.team,p.bx),ty=pyOf(p.by);p.sprint=p.energy>.5&&Math.hypot(tx-p.x,ty-p.y)>70;return seek(p,tx,ty,1)}
  if(p.job==="cover"&&o){const gx=sd(p.team)===0?X0:X1;return seek(p,b.x+(gx-b.x)*.32,b.y+(H/2-b.y)*.3,.95)}
  if(p.job==="run"){
    p.sprint=p.energy>.55&&st.counter>.5;
    /* a linha de fora de jogo mexe-se: quem corre nas costas da defesa acompanha-a e nunca fica para lá dela */
    if(o&&o.team===p.team&&!(typeof PREF!=="undefined"&&PREF.offsideVar===false)){
      const dir=sd(p.team)===0?1:-1,lineX=pxOf(p.team,deepestDef(p.team)),tx=pxOf(p.team,p.bx),lim=lineX-dir*(6+Math.hypot(p.vx,p.vy)*9);      // margem: a travagem do corredor
      return seek(p,dir*tx>dir*lim?lim:tx,pyOf(p.by),dir*p.x>dir*lim?.6:.9);
    }
  }
  seek(p,pxOf(p.team,p.bx),pyOf(p.by),o&&o.team===p.team?.85:.8);
}
function bestPassTarget(p,st){
  let best=null,bs=-1e9;
  for(const q of G.players){
    if(q.off||q.team!==p.team||q===p||q.role==="GK")continue;
    const d=dist(p,q);if(d<50||d>440||!laneClear(p,q)||wouldBeOffside(p,q))continue;
    const adv=nxOf(p.team,q.x)-nxOf(p.team,p.x),s=adv*300*(.5+st.risk)+Math.min(minOppDist(q),120)*.6-d/8-(adv<0?30*(1-st.risk*.5):0);
    if(s>bs){bs=s;best=q}
  }
  return best?{p:best,score:bs}:null;
}
function aiCarrier(p){
  const D=p.team===1?G.D:MATE,st=p.team===1?STYLES[G.styleR]:STYLES.posse;
  const gx=sd(p.team)===0?X1:X0,dir=sd(p.team)===0?1:-1,dGoal=Math.hypot(gx-p.x,H/2-p.y),press=minOppDist(p);
  p.sprint=false;
  if(p.think<=0){
    p.think=D.think*st.tempo*rnd(.8,1.25);
    const opts=[];
    if(dGoal<340){const ang=Math.abs(Math.atan2(H/2-p.y,Math.abs(gx-p.x)));let s=(340-dGoal)/2.4-ang*30+(press>40?15:0);if(dGoal<200)s+=35;opts.push({k:"shoot",s})}
    const q=bestPassTarget(p,st);
    if(q)opts.push({k:"pass",s:q.score*.25+(press<45?35:0)-(dGoal<170?40:0)+(st.tempo<1?10:0),q:q.p});
    opts.push({k:"dribble",s:20+(press>70?30:0)-(press<30?30:0)});
    opts.sort((a,c)=>c.s-a.s);
    let pick=opts[0];
    if(Math.random()>D.dec&&opts.length>1)pick=opts[1+Math.floor(Math.random()*(opts.length-1))];
    if(pick.k==="shoot"&&pick.s>10){aiShoot(p,D);return}
    if(pick.k==="pass"){passTo(p,pick.q,D.noise);return}
  }
  let ty=H/2+(p.y-H/2)*.6,near=null,nd=1e9;
  for(const q of G.players){if(q.off||q.team===p.team)continue;if((q.x-p.x)*dir<-5)continue;const d=dist(p,q);if(d<nd){nd=d;near=q}}
  if(near&&nd<90)ty=p.y+(p.y>near.y?1:-1)*120;
  p.sprint=p.energy>.45&&(st.counter>.5?nd>60:nd>120);
  seek(p,gx,clamp(ty,Y0+30,Y1-30),.92);
}
function aiGK(p){
  const D=p.team===1?G.D:MATE,b=G.ball,lineX=sd(p.team)===0?X0+14:X1-14,dir=sd(p.team)===0?1:-1;
  p.sprint=false;
  if(p.gkDown>0){p.dx=p.dy=0;return}
  if(b.owner===p){p.dx=p.dy=0;p.fx=dir;p.fy=0;if(p.gkHold<=0&&G.state==="play")gkDistribute(p);return}
  const towards=sd(p.team)===0?b.vx<-1:b.vx>1;
  if(b.pend&&b.pend.type==="shot"&&b.pend.team!==p.team&&towards&&!b.owner){
    const sp0=Math.hypot(b.vx,b.vy);
    const sk=gkSkill(p);
    if(sp0>3.4&&(b.kt||0)*DT>D.react*(1.15-.2*sk)){const tt=(lineX-b.x)/b.vx;
      if(tt>0&&tt<=19){
        /* o guarda-redes lê a trajetória com erro: maior em remates fortes e de perto, e em guarda-redes menos bons; o erro fixa-se ao ler o remate */
        if(p.gkPend!==b.pend){p.gkPend=b.pend;p.gkErr=(Math.random()+Math.random()+Math.random()-1.5)*2*(1.45-sk)*(9+sp0*1.7)*(tt<7?1.25:1)}
        const zA=b.z+b.vz*tt-.5*GRAV*tt*tt;      // altura estimada à chegada à linha
        if(zA>BAR_H+3)return seek(p,lineX,clamp(b.y,GY0+6,GY1-6),1);      // vai por cima da barra: não se atira
        let py=clamp(b.y+b.vy*tt+p.gkErr,GY0-2,GY1+2);if(b.pend.pen){if(p.penPick==null){const r=Math.random();p.penPick=r<.3*D.gk?py:(r<.42?H/2:(Math.random()<.5?GY0+16:GY1-16))}py=p.penPick}const need=py-p.y;
        if(Math.abs(need)>10&&Math.abs(need)<90){gkDive(p,py,tt,need,zA);return}
        if(tt<12&&Math.abs(need)<=10&&(sp0>6.5||zA>16)&&!(p.gkJump>0))p.gkJump=.6}}}
  if(!b.owner&&towards&&Math.abs(b.vx)>3&&(b.kt||0)*DT>D.react){const tt=(lineX-b.x)/b.vx;if(tt>0&&tt<70)return seek(p,lineX,clamp(b.y+b.vy*tt,GY0+6,GY1-6),1.25*D.gk)}
  const o=b.owner;
  if(o&&o.team!==p.team&&nxOf(p.team,o.x)<.16&&Math.abs(o.y-H/2)<150&&dist(o,p)<130)return seek(p,o.x-dir*8,o.y,1.1*D.gk);
  if(!o&&Math.hypot(b.x-lineX,b.y-H/2)<120&&Math.hypot(b.vx,b.vy)<6)return seek(p,b.x,b.y,1.1);
  const gcx=sd(p.team)===0?X0:X1,dx=b.x-gcx,dy=b.y-H/2,d=Math.hypot(dx,dy)||1,r=18+(1-Math.min(1,d/600))*30;
  seek(p,gcx+dx/d*r,clamp(H/2+dy/d*r,GY0+8,GY1-8),1.05);
}
/* qualidade do guarda-redes: dificuldade da equipa × atributo do jogador */
function gkSkill(p){const D=p.team===1?G.D:MATE;return clamp(D.gk*(.85+.3*((p.rating||70)-60)/40),.55,1.25)}
/* mergulho: o tempo no chão é proporcional à distância percorrida (mergulhos curtos recuperam depressa); bola alta combina salto com mergulho */
function gkDive(p,py,tt,need,zA){const side=need>0?1:-1,v=Math.min(4.6+1.2*gkSkill(p),Math.abs(need)/Math.max(5,tt)*1.15+1);p.dive={ty:py,side,t:0,dur:.5,v};p.gkDown=.75+.55*Math.min(1,Math.abs(need)/90);p.dx=p.dy=0;p.vy=side*v*.5;p.sprint=false;if(zA>16)p.gkJump=.6}
function gkDistribute(p){
  const st=p.team===1?STYLES[G.styleR]:STYLES.posse,long=Math.random()<st.gkLong;let best=null,bs=-1e9;
  for(const q of G.players){if(q.off||q.team!==p.team||q===p)continue;const s=Math.min(minOppDist(q),140)+(q.role==="D"?20:0)-Math.abs(q.y-p.y)*.08+(long&&q.role==="F"?70:0);if(laneClear(p,q)&&s>bs){bs=s;best=q}}
  const tgt=best||nearestOf(p.team,{x:W/2,y:H/2},false),hand=!long&&tgt&&dist(p,tgt)<230;      // curta: lançamento com a mão (mais preciso, menos força); longa: pontapé de baliza
  passTo(p,tgt,hand?.45:.9,hand?7.2:11);
}

/* ================= Replay ================= */
function recordFrame(){
  const a=G.rb;let k=G.rbHead*RF;
  for(const p of G.players){a[k++]=p.x;a[k++]=p.y;a[k++]=p.fx;a[k++]=p.fy;a[k++]=p.run;a[k++]=(p.stun>0?1:0)|(Math.hypot(p.vx,p.vy)>.3?2:0)|(p.off?4:0)|(p.dive?(8|(p.dive.side>0?16:0)|(Math.min(63,Math.floor(p.dive.t*40))<<5)):0)}
  a[k++]=G.ball.x;a[k++]=G.ball.y;a[k++]=G.hot>0?1:0;a[k++]=G.players.indexOf(G.ctrl);a[k++]=G.ball.z||0;
  G.rbHead=(G.rbHead+1)%RN;G.rbCount=Math.min(RN,G.rbCount+1);
}
function startReplay(){
  const n=Math.min(G.rbCount,210),buf=new Float32Array(n*RF);
  for(let i=0;i<n;i++){const src=((G.rbHead-n+i)%RN+RN)%RN;buf.set(G.rb.subarray(src*RF,src*RF+RF),i*RF)}
  G.replay={buf,n,f:0};G.state="replay";G.msg="";G.parts.length=0;G.net=null;
  const sk=document.getElementById("skipBtn");if(sk)sk.hidden=false;
}
function endReplay(){G.replay=null;G.rv=null;const sk=document.getElementById("skipBtn");if(sk)sk.hidden=true;setupKickoff(G.nextKick)}
function replayView(){
  const R=G.replay,fi=Math.min(R.n-1,Math.floor(R.f)),a=R.buf;
  const V=G.rv||(G.rv=G.players.map(p=>({team:p.team,role:p.role,num:p.num,x:0,y:0,fx:0,fy:0,run:0,stun:0,vx:0,vy:0,off:false,energy:1})));
  let k=fi*RF;
  for(const v of V){v.x=a[k++];v.y=a[k++];v.fx=a[k++];v.fy=a[k++];v.run=a[k++];const fl=a[k++];v.stun=fl&1?1:0;v.vx=fl&2?1:0;v.off=!!(fl&4);v.dive=fl&8?{t:((fl>>5)&63)/40,side:fl&16?1:-1}:null}
  const bx=a[k++],by=a[k++],hot=a[k++],ci=a[k++],bz=a[k++],tr=[];
  for(let j=Math.max(0,fi-12);j<fi;j++){const x1=a[j*RF+NP*6],y1=a[j*RF+NP*6+1],x2=a[(j+1)*RF+NP*6],y2=a[(j+1)*RF+NP*6+1];if(Math.hypot(x2-x1,y2-y1)>4)tr.push({x:x1,y:y1})}
  return{players:V,ball:{x:bx,y:by,z:bz},ctrl:ci>=0?V[ci]:null,hot:hot>0,trail:tr,charging:false,replay:true};
}

/* ================= Efeitos ================= */
const fxN=n=>PREF.reduceFx?Math.ceil(n*.3):n;
function burst(k,x,y,n,cols,spd,life,size){n=fxN(n);for(let i=0;i<n;i++){const a=Math.random()*Math.PI*2,v=rnd(spd*.3,spd);G.parts.push({k,x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,life:life*rnd(.6,1),max:life,size:size*rnd(.6,1.2),col:cols[i%cols.length],rot:Math.random()*6,vr:rnd(-.2,.2)})}}
function ring(x,y,col){G.parts.push({k:"ring",x,y,vx:0,vy:0,life:.32,max:.32,size:4,col})}
function confColors(t){const c=cosm("confetti").id;if(c==="clube")return[G.cols[t].c1,G.cols[t].c2,"#ffffff"];if(c==="ouro")return["#f2b705","#ffd95a","#fff1b8","#c99700"];return["#c8102e","#151515","#f2b705",G.cols[t].c1]}
function confetti(t,n){const cols=confColors(t);n=fxN(n);
  for(let i=0;i<n;i++){const top=Math.random()<.5;G.parts.push({k:"conf",x:rnd(X0,X1),y:top?rnd(8,40):rnd(580,612),vx:rnd(-1.5,1.5),vy:top?rnd(1,4):rnd(-6.5,-3),life:rnd(1.8,3.2),max:3.2,size:rnd(3.5,6.5),col:cols[i%cols.length],rot:Math.random()*6,vr:rnd(-.25,.25)})}}
function goalFx(t){confetti(t,170);burst("spark",G.ball.x,G.ball.y,28,["#ffffff","#f2b705"],5,.6,3)}
function updateFx(){
  const P=G.parts;
  for(let i=P.length-1;i>=0;i--){const q=P[i];q.life-=DT;if(q.life<=0){P.splice(i,1);continue}
    q.x+=q.vx;q.y+=q.vy;
    if(q.k==="conf"){q.vy+=.045;q.vx*=.985;q.vy*=.985;q.rot+=q.vr}
    else if(q.k==="dust"){q.vx*=.9;q.vy*=.9;q.size+=.22}
    else if(q.k==="spark"){q.vx*=.92;q.vy*=.92}}
  if(G.flashT>0){G.flashT-=DT;if(Math.random()<.7)for(let n=0;n<2;n++)P.push({k:"cam",x:rnd(4,W-4),y:Math.random()<.5?rnd(6,32):rnd(590,616),vx:0,vy:0,life:.14,max:.14,size:rnd(2.5,5)})}
  if(G.net){G.net.amp*=.965;if(G.net.amp<.02)G.net=null}
  const b=G.ball,s=Math.hypot(b.vx,b.vy);
  if(b.owner)G.hot=0;else if(G.hot>0)G.hot-=DT;
  if(!b.owner&&s>5){G.trail.push({x:b.x,y:b.y});if(G.trail.length>14)G.trail.shift()}else if(G.trail.length)G.trail.shift();
  if(G.hot>0&&s>4&&Math.random()<(PREF.reduceFx?.25:.85))P.push({k:"spark",x:b.x,y:b.y,vx:rnd(-.7,.7),vy:rnd(-.7,.7),life:.35,max:.35,size:rnd(2,3.5),col:Math.random()<.5?"#ffb020":"#ff5a1f"});
  if(P.length>600)P.splice(0,P.length-600);
}

/* ================= Som ================= */
let AC=null,NOISE=null,AMB=null,nextBeat=0,beatI=0;
function ac(){try{if(!AC){AC=new(window.AudioContext||window.webkitAudioContext)();const n=AC.sampleRate*2;NOISE=AC.createBuffer(1,n,AC.sampleRate);const d=NOISE.getChannelData(0);for(let i=0;i<n;i++)d[i]=Math.random()*2-1}if(AC.state==="suspended")AC.resume()}catch(e){AC=null}return AC}
function env(g,t,a,peak,dur){g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(peak,t+a);g.gain.exponentialRampToValueAtTime(.0001,t+dur)}
function sfx(k,v){
  if(!PREF.sound||!AC)return;try{
  const t=AC.currentTime,g=AC.createGain();g.connect(AC.destination);
  if(k==="kick"){const o=AC.createOscillator();o.frequency.setValueAtTime(170,t);o.frequency.exponentialRampToValueAtTime(55,t+.09);o.connect(g);env(g,t,.005,Math.min(.5,.08+(v||6)*.025),.12);o.start(t);o.stop(t+.13)}
  else if(k==="switch"){const o=AC.createOscillator();o.type="triangle";o.frequency.value=880;o.connect(g);env(g,t,.003,.05,.06);o.start(t);o.stop(t+.07)}
  else if(k==="tackle"){const s=AC.createBufferSource(),f=AC.createBiquadFilter();f.type="lowpass";f.frequency.value=900;s.buffer=NOISE;s.connect(f);f.connect(g);env(g,t,.005,.35,.12);s.start(t);s.stop(t+.13)}
  else if(k==="whistle"){const n=v||1;for(let i=0;i<n;i++){const t0=t+i*.32,dur=i===n-1&&n>1?.55:.26,o=AC.createOscillator(),l=AC.createOscillator(),lg=AC.createGain(),gg=AC.createGain();o.type="triangle";o.frequency.value=2650;l.frequency.value=32;lg.gain.value=140;l.connect(lg);lg.connect(o.frequency);o.connect(gg);gg.connect(AC.destination);env(gg,t0,.02,.09,dur);o.start(t0);l.start(t0);o.stop(t0+dur+.02);l.stop(t0+dur+.02)}}
  else if(k==="goal"){const s=AC.createBufferSource(),f=AC.createBiquadFilter();f.type="bandpass";f.frequency.value=800;f.Q.value=.6;s.buffer=NOISE;s.loop=true;s.connect(f);f.connect(g);g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(.5,t+.25);g.gain.exponentialRampToValueAtTime(.0001,t+2.2);s.start(t);s.stop(t+2.3)}
  }catch(e){}
}
function ambientStart(){if(!PREF.sound||!ac()||AMB)return;try{const s=AC.createBufferSource(),f=AC.createBiquadFilter(),g=AC.createGain();f.type="lowpass";f.frequency.value=520;s.buffer=NOISE;s.loop=true;g.gain.value=.03;s.connect(f);f.connect(g);g.connect(AC.destination);s.start();AMB={s,g};nextBeat=AC.currentTime+.3}catch(e){}}
function ambientStop(){if(AMB){try{AMB.s.stop()}catch(e){}AMB=null}}
// Batuque: padrão simples de tambores que acompanha a partida
const BEAT=[1,0,.6,1,0,.6,.8,0];
function drums(){
  if(!AMB||!G||G.paused||G.state!=="play")return;
  if(AC.currentTime<nextBeat-.05)return;
  const v=BEAT[beatI++%BEAT.length],t=Math.max(AC.currentTime,nextBeat);nextBeat=t+.19;
  if(!v)return;try{const o=AC.createOscillator(),g=AC.createGain();o.frequency.setValueAtTime(v>.9?110:150,t);o.frequency.exponentialRampToValueAtTime(60,t+.12);o.connect(g);g.connect(AC.destination);env(g,t,.004,.05*v,.16);o.start(t);o.stop(t+.18)}catch(e){}
}

/* ================= Desenho ================= */
let canvas=null,ctx=null,bg=null,DPR=1,SC=1,VW=1000,VH=620,OX=0,OY=0;
function makeCrowd(){
  const home=G.o.homeLeft?0:1,hc=G.cols[home],aw=G.cols[1-home];
  const pick=()=>{const r=Math.random();if(r<.5)return Math.random()<.65?hc.c1:hc.c2;if(r<.68)return Math.random()<.65?aw.c1:aw.c2;if(r<.8)return["#c8102e","#151515","#f2b705"][Math.random()*3|0];return["#e8e2cf","#9a8f78","#5d5547","#2a2a2a"][Math.random()*4|0]};
  const pts=[];
  for(let y=4;y<34;y+=6)for(let x=2;x<W;x+=6)pts.push([x+rnd(-1,1),y,pick()]);
  for(let y=588;y<618;y+=6)for(let x=2;x<W;x+=6)pts.push([x+rnd(-1,1),y,pick()]);
  for(let x=2;x<34;x+=6)for(let y=40;y<580;y+=6)if(Math.abs(y-H/2)>GH/2+16){pts.push([x,y,pick()]);pts.push([W-x-3,y,pick()])}
  return pts;
}
/* O canvas ocupa todo o palco. O jogo desenha-se num espaço virtual VW×VH com escala uniforme SC;
   a janela de desenho original W×H fica centrada com o deslocamento (OX,OY). */
function resize(){
  if(!G||!canvas)return;const st=document.getElementById("stage");if(!st)return;
  const r=st.getBoundingClientRect(),cw=Math.max(1,r.width),ch=Math.max(1,r.height),asp=cw/ch;
  DPR=Math.min(PREF.quality==="low"?1:PREF.quality==="medium"?1.5:2,window.devicePixelRatio||1);
  if(PREF.camera==="top"){SC=Math.max(.2,Math.min(cw/W,ch/H))}
  else if(asp>=W/H){SC=Math.max(ch/H,cw/(W+500))}
  else{const TW=asp<.9?720:720+(W-720)*Math.min(1,(asp-.9)/(W/H-.9));SC=Math.max(cw/TW,ch/(H*1.9))}
  VW=cw/SC;VH=ch/SC;OX=(VW-W)/2;OY=(VH-H)/2;
  canvas.style.width=cw+"px";canvas.style.height=ch+"px";canvas.width=Math.max(1,Math.round(cw*DPR));canvas.height=Math.max(1,Math.round(ch*DPR));
  bg=document.createElement("canvas");bg.width=canvas.width;bg.height=canvas.height;drawBg(bg.getContext("2d"));
  const rh=document.getElementById("rotHint");if(rh)rh.hidden=!(innerHeight>innerWidth);
  const tb=document.querySelector(".tbtns");if(tb){const k=Math.max(.55,Math.min(1.3,Math.min(ch/340,cw/640)*(PREF.touchScale||1)));tb.style.setProperty("--tk",k.toFixed(3))}
}
const TF=c=>c.setTransform(DPR*SC,0,0,DPR*SC,DPR*SC*OX,DPR*SC*OY);
const TU=c=>c.setTransform(DPR*SC,0,0,DPR*SC,0,0);
function drawBg(c){
  TU(c);c.fillStyle="#0a1a12";c.fillRect(0,0,VW,VH);TF(c);
  c.fillStyle="#0a1a12";c.fillRect(0,0,W,H);
  if(!G.crowd)G.crowd=makeCrowd();
  for(const [x,y,col] of G.crowd){c.globalAlpha=.55+Math.random()*.4;c.fillStyle=col;c.fillRect(x,y,3.2,3.2)}
  c.globalAlpha=1;
  // faixas de adeptos (texto genérico) e placas à volta do campo
  const home=G.o.homeLeft?0:1,ht=G.teams[home];
  const banners=[[120,6,`FORÇA ${ht.s}`,G.cols[home].c1,G.cols[home].c2],[430,6,"GIRABOLA",  "#151515","#f2b705"],[740,6,`${ht.s} ATÉ AO FIM`,G.cols[home].c2,G.cols[home].c1],[260,592,"KAMBAS DA BANCADA","#c8102e","#ffffff"],[600,592,"BOLA NO PÉ","#151515","#f2b705"]];
  c.font='700 13px "Rajdhani","Arial Narrow",sans-serif';c.textBaseline="middle";c.textAlign="center";
  for(const [x,y,txt,bgc,fg] of banners){const w=c.measureText(txt).width+22;c.fillStyle=bgc;c.fillRect(x-w/2,y,w,20);c.fillStyle=fg;c.fillText(txt,x,y+10.5)}
  c.fillStyle="#08130d";c.fillRect(X0,Y0-7,X1-X0,5);c.fillRect(X0,Y1+2,X1-X0,5);
  const sw=(X1-X0)/12,mow=["#2e7b3a","#287034"];
  for(let i=0;i<12;i++){c.fillStyle=i%2?mow[0]:mow[1];c.fillRect(X0+i*sw,Y0,sw+.5,Y1-Y0)}
  c.strokeStyle="rgba(255,255,255,.82)";c.lineWidth=2.2;c.fillStyle="rgba(255,255,255,.85)";
  c.strokeRect(X0,Y0,X1-X0,Y1-Y0);
  c.beginPath();c.moveTo(W/2,Y0);c.lineTo(W/2,Y1);c.stroke();
  c.beginPath();c.arc(W/2,H/2,62,0,Math.PI*2);c.stroke();
  c.beginPath();c.arc(W/2,H/2,3,0,Math.PI*2);c.fill();
  for(const s of [0,1]){
    const gx=s?X1:X0,d=s?-1:1;
    c.strokeRect(s?X1-140:X0,H/2-160,140,320);c.strokeRect(s?X1-48:X0,H/2-90,48,180);
    c.beginPath();c.arc(gx+d*100,H/2,3,0,Math.PI*2);c.fill();
    const a=Math.acos(40/62);c.beginPath();if(s)c.arc(X1-100,H/2,62,Math.PI-a,Math.PI+a);else c.arc(X0+100,H/2,62,-a,a);c.stroke();
    const nx=s?X1:X0-26;c.fillStyle="rgba(255,255,255,.07)";c.fillRect(nx,GY0,26,GH);
    c.save();c.strokeStyle="rgba(255,255,255,.22)";c.lineWidth=1;c.beginPath();
    for(let y=GY0;y<=GY1;y+=7){c.moveTo(nx,y);c.lineTo(nx+26,y)}for(let x=nx;x<=nx+26;x+=7){c.moveTo(x,GY0);c.lineTo(x,GY1)}c.stroke();c.restore();
    c.save();c.strokeStyle="#fff";c.lineWidth=4;c.beginPath();c.moveTo(gx,GY0);c.lineTo(gx+(s?26:-26),GY0);c.lineTo(gx+(s?26:-26),GY1);c.lineTo(gx,GY1);c.stroke();c.restore();
    c.fillStyle="rgba(255,255,255,.85)";
  }
  for(const [x,y,a0] of [[X0,Y0,0],[X1,Y0,Math.PI/2],[X1,Y1,Math.PI],[X0,Y1,-Math.PI/2]]){c.beginPath();c.arc(x,y,10,a0,a0+Math.PI/2);c.stroke()}
  c.globalCompositeOperation="lighter";
  for(const [x,y] of [[0,0],[W,0],[0,H],[W,H]]){const g=c.createRadialGradient(x,y,0,x,y,560);g.addColorStop(0,"rgba(255,248,215,.17)");g.addColorStop(1,"rgba(255,248,215,0)");c.fillStyle=g;c.fillRect(0,0,W,H)}
  c.globalCompositeOperation="source-over";
  const v=c.createRadialGradient(W/2,H/2,H*.38,W/2,H/2,W*.64);v.addColorStop(0,"rgba(0,0,0,0)");v.addColorStop(1,"rgba(0,0,0,.38)");c.fillStyle=v;c.fillRect(0,0,W,H);
  c.save();c.shadowColor="#fff6c8";c.shadowBlur=14;c.fillStyle="#fffbea";
  for(const [x,y] of [[8,8],[W-26,8],[8,H-26],[W-26,H-26]])for(let i=0;i<3;i++)for(let j=0;j<2;j++)c.fillRect(x+i*6.5,y+j*6.5,5,5);
  c.restore();
}
function drawBall(c,x,y){
  const id=cosm("ball").id,base=id==="girassol"?"#ffd23f":id==="diamante"?"#d9f3ff":"#ffffff",patch=id==="girassol"?"#1d4e9e":id==="diamante"?"#3ec1ff":"#1b1b1f";
  const g=c.createRadialGradient(x-1.6,y-1.8,.4,x,y,5.4);g.addColorStop(0,"#ffffff");g.addColorStop(.55,base);g.addColorStop(1,shade(base,-.32));
  c.fillStyle=g;c.beginPath();c.arc(x,y,5,0,Math.PI*2);c.fill();
  if(id==="rubro"){c.save();c.beginPath();c.arc(x,y,5,0,Math.PI*2);c.clip();c.fillStyle="#c8102e";c.fillRect(x-5,y-5,5.2,10);c.fillStyle="rgba(0,0,0,.2)";c.fillRect(x-5,y+1.5,10,3.5);c.restore();}
  else if(id==="diamante"){c.strokeStyle=patch;c.lineWidth=.9;c.beginPath();c.moveTo(x,y-4);c.lineTo(x+3.4,y);c.lineTo(x,y+4);c.lineTo(x-3.4,y);c.closePath();c.moveTo(x-3.4,y);c.lineTo(x+3.4,y);c.stroke()}
  else{ // pentágonos
    c.fillStyle=patch;const pent=(cx,cy,r,rot)=>{c.beginPath();for(let i=0;i<5;i++){const a=rot+i*Math.PI*2/5;i?c.lineTo(cx+Math.cos(a)*r,cy+Math.sin(a)*r):c.moveTo(cx+Math.cos(a)*r,cy+Math.sin(a)*r)}c.closePath();c.fill()};
    pent(x+.7,y-.4,1.9,-Math.PI/2);pent(x-3.5,y+1.2,1.15,.4);pent(x+3.4,y+2,1.0,1.1);pent(x-.6,y+4,.9,2.2);pent(x+2.4,y-3.7,.9,-.6)}
  c.strokeStyle="rgba(0,0,0,.35)";c.lineWidth=.5;c.beginPath();c.arc(x,y,5,0,Math.PI*2);c.stroke();
}
let FRAME=0;
function render(){
  FRAME++;
  const V=G.state==="replay"&&G.replay?replayView():{players:G.players,ball:G.ball,ctrl:G.ctrl,hot:G.hot>0,trail:G.trail,charging:G.charging};
  if(PREF.camera!=="top"){renderTV(ctx,V);return}
  const c=ctx;c.setTransform(1,0,0,1,0,0);c.drawImage(bg,0,0);
  TF(c);
  if(G.shake>0&&!PREF.reduceFx)c.translate(rnd(-1,1)*G.shake*9,rnd(-1,1)*G.shake*9);
  drawAmbient(c);
  if(G.net){const n=G.net,a=n.amp,t=performance.now()/90;c.strokeStyle=`rgba(255,255,255,${.75*a})`;c.lineWidth=1.4;
    for(const off of [7,14,21,26]){const x=n.x+n.dir*off,bul=n.dir*a*(6+off*.45)*(.75+.25*Math.sin(t+off));c.beginPath();c.moveTo(x,GY0);c.quadraticCurveTo(x+bul,n.y,x,GY1);c.stroke()}}
  if(G.tut&&G.tut.marker){const m=G.tut.marker,pl=1+Math.sin(performance.now()/180)*.12;c.strokeStyle="#f2b705";c.lineWidth=3;c.beginPath();c.arc(m.x,m.y,22*pl,0,Math.PI*2);c.stroke();c.fillStyle="rgba(242,183,5,.18)";c.fill()}
  const b=V.ball,list=V.players.filter(p=>!p.off).sort((a,q)=>a.y-q.y),mk=cosm("marker").c;
  for(const p of list){c.fillStyle="rgba(0,0,0,.28)";c.beginPath();c.ellipse(p.x+2,p.y+8,10,4,0,0,Math.PI*2);c.fill()}
  c.fillStyle="rgba(0,0,0,.3)";c.beginPath();c.ellipse(b.x+2,b.y+4,5,2.4,0,0,Math.PI*2);c.fill();
  if(!V.replay&&G.passTarget&&!G.passTarget.off){const q=G.passTarget;c.save();c.setLineDash([4,4]);c.strokeStyle="rgba(255,255,255,.7)";c.lineWidth=2;c.beginPath();c.arc(q.x,q.y,16,0,Math.PI*2);c.stroke();c.restore()}
  for(const p of list){
    const col=G.cols[p.team];c.globalAlpha=p.stun>0?.55:1;
    const spd=Math.hypot(p.vx,p.vy);
    if(spd>.3){const ph=Math.sin(p.run||0)*4*Math.min(1,spd/2),nx=-p.fy,ny=p.fx,ang=Math.atan2(p.fy,p.fx);c.fillStyle="#141414";
      for(const sg of [1,-1]){const o=ph*sg;c.beginPath();c.ellipse(p.x+nx*5*sg+p.fx*o,p.y+ny*5*sg+p.fy*o,3.4,2.2,ang,0,Math.PI*2);c.fill()}}
    if(p===V.ctrl&&V.charging){const r=16+G.charge*16,g=c.createRadialGradient(p.x,p.y,4,p.x,p.y,r);g.addColorStop(0,`rgba(242,183,5,${.25+G.charge*.45})`);g.addColorStop(1,"rgba(242,183,5,0)");c.fillStyle=g;c.beginPath();c.arc(p.x,p.y,r,0,Math.PI*2);c.fill()}
    if(p===V.ctrl){c.strokeStyle=mk;c.lineWidth=2.5;c.beginPath();c.arc(p.x,p.y,15,0,Math.PI*2);c.stroke()}
    c.fillStyle=col.c1;c.strokeStyle=col.c2;c.lineWidth=3;c.beginPath();c.arc(p.x,p.y,10,0,Math.PI*2);c.fill();c.stroke();
    if(p.role==="GK"){c.fillStyle=p.team===0?"#22d3c5":"#ff8a3d";c.beginPath();c.arc(p.x,p.y,5,0,Math.PI*2);c.fill()}
    else{c.fillStyle=col.c2;c.font='700 11px "Rajdhani","Arial Narrow",sans-serif';c.textAlign="center";c.textBaseline="middle";c.fillText(p.num,p.x,p.y+.5)}
    c.globalAlpha=1;
    if(p===V.ctrl){
      c.fillStyle=mk;c.beginPath();c.moveTo(p.x-6,p.y-24);c.lineTo(p.x+6,p.y-24);c.lineTo(p.x,p.y-17);c.closePath();c.fill();
      if(!V.replay){const e=p.energy;c.fillStyle="rgba(0,0,0,.5)";c.fillRect(p.x-13,p.y+15,26,4);c.fillStyle=p.tired?"#d7263d":e<.3?"#f2b705":"#4cc38a";c.fillRect(p.x-13,p.y+15,26*e,4)}
      if(V.charging){c.fillStyle="rgba(0,0,0,.5)";c.fillRect(p.x-18,p.y-34,36,6);c.fillStyle=G.charge>.85?"#d7263d":"#f2b705";c.fillRect(p.x-18,p.y-34,36*G.charge,6)}
    }
  }
  const tr=V.trail;for(let i=0;i<tr.length;i++){const a=(i+1)/tr.length;c.globalAlpha=a*.5;c.fillStyle=V.hot?(i%2?"#ff5a1f":"#ffb020"):"#ffffff";c.beginPath();c.arc(tr[i].x,tr[i].y,5*a+.5,0,Math.PI*2);c.fill()}c.globalAlpha=1;
  if(V.hot){const g=c.createRadialGradient(b.x,b.y,2,b.x,b.y,20);g.addColorStop(0,"rgba(255,170,40,.9)");g.addColorStop(1,"rgba(255,80,20,0)");c.fillStyle=g;c.beginPath();c.arc(b.x,b.y,20,0,Math.PI*2);c.fill()}
  drawBall(c,b.x,b.y);
  drawParts(c);
  TU(c);
  if(G.flash>0&&!PREF.reduceFx){c.fillStyle=`rgba(255,255,255,${G.flash*.5})`;c.fillRect(0,0,VW,VH)}
  if(V.replay){c.fillStyle="rgba(0,0,0,.55)";c.fillRect(0,0,VW,26);c.fillRect(0,VH-26,VW,26);c.font='700 22px Rajdhani,"Arial Narrow",sans-serif';c.textAlign="left";c.textBaseline="middle";c.fillStyle=FRAME%60<40?"#d7263d":"#7a1220";c.beginPath();c.arc(30,13,6,0,Math.PI*2);c.fill();c.fillStyle="#fff";c.fillText("REPLAY",44,14)}
  drawMsg(c);
}
function drawAmbient(c){
  if(PREF.reduceFx)return;
  const t=performance.now()/1000;
  // onda do público a percorrer as bancadas
  const wx=((t*160)%(W+300))-150;
  const g=c.createLinearGradient(wx-80,0,wx+80,0);g.addColorStop(0,"rgba(255,240,180,0)");g.addColorStop(.5,"rgba(255,240,180,.16)");g.addColorStop(1,"rgba(255,240,180,0)");
  c.fillStyle=g;c.fillRect(wx-80,0,160,36);c.fillRect(W-wx-80,584,160,36);
  // bandeiras a ondular
  const home=G.o.homeLeft?0:1,cols=[[G.cols[home].c1,G.cols[home].c2],[ "#c8102e","#151515"],[G.cols[1-home].c1,G.cols[1-home].c2]];
  const spots=[[28,2],[292,2],[582,2],[900,2],[120,586],[440,586],[860,586]];
  spots.forEach(([x,y],i)=>{const [a,b2]=cols[i%3];c.fillStyle="#3a3a3a";c.fillRect(x,y,1.5,30);for(let k=0;k<2;k++){c.fillStyle=k?b2:a;c.beginPath();const yy=y+2+k*6;c.moveTo(x+1.5,yy);for(let s=0;s<=22;s+=2){c.lineTo(x+1.5+s,yy+Math.sin(t*6+s*.35+i)*1.6)}for(let s=22;s>=0;s-=2){c.lineTo(x+1.5+s,yy+6+Math.sin(t*6+s*.35+i)*1.6)}c.fill()}});
}
function drawParts(c){
  for(const q of G.parts){const a=Math.max(0,q.life/q.max);
    if(q.k==="conf"){c.save();c.translate(q.x,q.y);c.rotate(q.rot);c.globalAlpha=Math.min(1,a*2);c.fillStyle=q.col;c.fillRect(-q.size/2,-q.size/4,q.size,q.size/2*(.35+Math.abs(Math.sin(q.rot*2))));c.restore()}
    else if(q.k==="ring"){c.globalAlpha=a;c.strokeStyle=q.col;c.lineWidth=2.5;c.beginPath();c.arc(q.x,q.y,q.size+(1-a)*22,0,Math.PI*2);c.stroke()}
    else if(q.k==="dust"){c.globalAlpha=a*.5;c.fillStyle=q.col;c.beginPath();c.arc(q.x,q.y,q.size,0,Math.PI*2);c.fill()}
    else if(q.k==="spark"){c.globalAlpha=a;c.fillStyle=q.col;c.beginPath();c.arc(q.x,q.y,q.size*a+.5,0,Math.PI*2);c.fill()}
    else if(q.k==="cam"){c.globalAlpha=a*.35;c.fillStyle="#ffffff";c.beginPath();c.arc(q.x,q.y,q.size*2.6,0,Math.PI*2);c.fill();c.globalAlpha=a;c.beginPath();c.arc(q.x,q.y,q.size*.8,0,Math.PI*2);c.fill()}
  }
  c.globalAlpha=1;
}
function drawMsg(c){
  if(!G.msg){G._lm="";return}
  if(G.msg!==G._lm){G._lm=G.msg;G._ms=performance.now()}
  const k=PREF.reduceFx?1:Math.min(1,(performance.now()-G._ms)/340),e=1+2.7*Math.pow(k-1,3)+1.7*Math.pow(k-1,2);
  const big=G.msg==="GOLO!",small=G.state==="setpiece";
  const tbh=((document.querySelector(".topbar")||{}).offsetHeight||0)/SC;   // a faixa de cima é uma sobreposição: as mensagens ficam abaixo dela
  c.save();c.translate(VW/2,small?70+tbh:VH/2-14);c.scale(.4+.6*e,.4+.6*e);c.textAlign="center";c.textBaseline="middle";
  c.font=`700 ${big?104:small?30:52}px Rajdhani,"Arial Narrow",sans-serif`;c.lineJoin="round";
  c.lineWidth=big?14:small?7:10;c.strokeStyle="#0b0b0b";c.strokeText(G.msg,0,0);
  if(big){const g=c.createLinearGradient(0,-50,0,50);g.addColorStop(0,"#fff3b0");g.addColorStop(.5,"#f2b705");g.addColorStop(1,"#d7263d");c.fillStyle=g}else c.fillStyle="#ffffff";
  c.fillText(G.msg,0,0);c.restore();
  if(G.msgSub){const y=small?102+tbh:VH/2+(big?58:36);c.globalAlpha=k;c.textAlign="center";c.textBaseline="middle";c.font=`700 ${small?22:30}px "Rajdhani","Arial Narrow",sans-serif`;c.lineWidth=6;c.strokeStyle="rgba(0,0,0,.7)";c.strokeText(G.msgSub,VW/2,y);c.fillStyle="#fff";c.fillText(G.msgSub,VW/2,y);c.globalAlpha=1}
}

const KIT_LOOKS={"PET":{"shirt":"#ffd51e","accent":"#1643b9","shorts":"#1643b9","socks":"#ffce16","sleeve":"#1643b9","trim":"#df2428","pattern":6,"preview":"data:image/webp;base64,","crest":"data:image/png;base64,"},"1AG":{"shirt":"#cf1f27","accent":"#151515","shorts":"#151515","socks":"#cf1f27","sleeve":"#cf1f27","trim":"#ffffff","pattern":1,"preview":"data:image/webp;base64,","crest":"data:image/png;base64,"},"SAG":{"shirt":"#168347","accent":"#ffffff","shorts":"#ffffff","socks":"#168347","sleeve":"#168347","trim":"#ffffff","pattern":3,"preview":"data:image/webp;base64,","crest":"data:image/png;base64,"},"WIL":{"shirt":"#16833e","accent":"#ffdc15","shorts":"#16833e","socks":"#16833e","sleeve":"#16833e","trim":"#ffdc15","pattern":5,"preview":"data:image/webp;base64,","crest":"data:image/png;base64,"},"KAB":{"shirt":"#f5f5f0","accent":"#de2428","shorts":"#f5f5f0","socks":"#f5f5f0","sleeve":"#f5f5f0","trim":"#de2428","pattern":2,"preview":"data:image/webp;base64,","crest":"data:image/png;base64,"},"INT":{"shirt":"#151515","accent":"#245cc4","shorts":"#151515","socks":"#151515","sleeve":"#151515","trim":"#d3b24e","pattern":1,"preview":"data:image/webp;base64,","crest":"data:image/png;base64,"},"HUI":{"shirt":"#df2528","accent":"#151515","shorts":"#151515","socks":"#df2528","sleeve":"#df2528","trim":"#ffffff","pattern":2,"preview":"data:image/webp;base64,","crest":"data:image/png;base64,"},"SSA":{"shirt":"#df2428","accent":"#ffffff","shorts":"#ffffff","socks":"#df2428","sleeve":"#df2428","trim":"#ffffff","pattern":0,"preview":"data:image/webp;base64,","crest":"data:image/png;base64,"},"BRA":{"shirt":"#f5f5f1","accent":"#2359bc","shorts":"#2359bc","socks":"#f5f5f1","sleeve":"#f5f5f1","trim":"#2359bc","pattern":1,"preview":"data:image/webp;base64,","crest":"data:image/png;base64,"},"LIB":{"shirt":"#f5781c","accent":"#2455bb","shorts":"#2455bb","socks":"#f5781c","sleeve":"#f5781c","trim":"#2455bb","pattern":0,"preview":"data:image/webp;base64,","crest":"data:image/png;base64,"},"ACA":{"shirt":"#181818","accent":"#b29450","shorts":"#181818","socks":"#181818","sleeve":"#181818","trim":"#b29450","pattern":7,"preview":"data:image/webp;base64,","crest":"data:image/png;base64,"},"CAA":{"shirt":"#f5f5f2","accent":"#255ec5","shorts":"#255ec5","socks":"#f5f5f2","sleeve":"#f5f5f2","trim":"#255ec5","pattern":4,"preview":"data:image/webp;base64,","crest":"data:image/png;base64,"},"1MA":{"shirt":"#d82227","accent":"#ffffff","shorts":"#d82227","socks":"#d82227","sleeve":"#d82227","trim":"#ffffff","pattern":5,"preview":"data:image/webp;base64,","crest":"data:image/png;base64,"},"LSU":{"shirt":"#f5f5f2","accent":"#65bde5","shorts":"#f5f5f2","socks":"#65bde5","sleeve":"#f5f5f2","trim":"#65bde5","pattern":1,"preview":"data:image/webp;base64,","crest":"data:image/png;base64,"},"CAB":{"shirt":"#f5f5f2","accent":"#245bbb","shorts":"#245bbb","socks":"#245bbb","sleeve":"#f5f5f2","trim":"#245bbb","pattern":1,"preview":"data:image/webp;base64,","crest":"data:image/png;base64,"},"FCL":{"shirt":"#f5f5f2","accent":"#2357b9","shorts":"#f5f5f2","socks":"#f5f5f2","sleeve":"#f5f5f2","trim":"#2357b9","pattern":1,"preview":"data:image/webp;base64,","crest":"data:image/png;base64,"}};
