function showPick(mode,first){
  leaveMatch();
  const head={season:["Nova época","Escolhe o teu clube"],quick1:["Jogo rápido","Escolhe a tua equipa"],quick2:["Jogo rápido","Escolhe o adversário"]}[mode];
  const inProgress=mode==="season"&&S&&!seasonDone();
  app.innerHTML=`<section class="screen">
   <button class="back" id="pBack">${BACK}Voltar</button>
   <div><p class="eyebrow">${head[0]}</p><h2>${head[1]}</h2></div>
   ${mode==="season"?`<div class="opt"><span class="panel-title">Duração da época</span>${segHTML("legs",[["1","Uma volta · 15 jornadas"],["2","Duas voltas · 30 jornadas"]],String(PREF.legs))}<p class="note">Com duas voltas, cada jogo repete-se na segunda volta com casa e fora trocados.</p></div>`:""}
   <div id="confirm"></div>
   <div class="grid">${TEAMS.map((t,i)=>mode==="season"&&i>=BASE_N?"":`<button class="team" data-i="${i}" ${first===i?"disabled":""}>${crest(i,64)}<div style="min-width:0"><b>${t.n}</b><span>Força ${t.r} · ${STYLES[t.st].n}</span></div></button>`).join("")}</div>
   <p class="note">A força e o estilo de jogo de cada equipa são atribuídos pelo jogo e não são dados oficiais.</p>
  </section>`;
  on("pBack",()=>mode==="quick2"?showPick("quick1"):showMenu());
  bindSeg("legs",k=>{PREF.legs=+k;savePrefs()});
  app.querySelectorAll(".team").forEach(b=>b.onclick=()=>{
    const i=+b.dataset.i;
    if(mode==="season"){
      {newSeason(i,PREF.legs);showHub()}
    }
    else if(mode==="quick1")showPick("quick2",i);
    else showPrematch({L:first,R:i,homeLeft:true,mode:"quick"});
  });
  window.scrollTo(0,0);
}

function showPrematch(base){
  leaveMatch();
  const o={...base,diff:PREF.diff,rules:PREF.rules,tac:PREF.tactic,form:PREF.form};
  const R=TEAMS[o.R],st=STYLES[R.st],H=o.homeLeft?o.L:o.R,A=o.homeLeft?o.R:o.L;
  const STEPS=[["rules","Regras"],["team","Equipa"],["kit","Equipamento"],["stad","Estádio"],["ball","Bola"],["diff","Dificuldade"],["go","Pronto"]];
  const BALLS=[["auto","Automática","Clássica no campo do bairro e rubro-negra nos estádios."],["rubro_negra","Rubro-negra","Branca com lâminas pretas e filetes vermelhos."],["angola","Angola","Lâminas vermelhas, amarelas e pretas."],["azul","Azul","Triângulos azuis e azul-marinho."],["classica","Clássica","32 gomos pretos e brancos, gasta e suja."],["verde","Verde","Lâminas verdes com pinceladas pretas."]];
  const DIFFD={easy:"Adversários mais lentos e menos precisos. Ideal para aprender.",normal:"Equilíbrio entre desafio e diversão.",hard:"Adversários rápidos, precisos e agressivos."};
  const TIMED={night:"Holofotes, céu escuro e estrelas.",day:"Céu azul, nuvens e luz natural."};
  let step=0;
  const kg=(typeof G94!=="undefined"&&G94.kitPara)?G94:null,kDef=()=>kg?kg.kitPadrao(o.L):"home";
  const val={kit:()=>o.kit||kDef(),kitR:()=>o.kitR||"auto",rules:()=>o.rules,var:()=>PREF.offsideVar===false?"off":"on",tac:()=>o.tac,form:()=>o.form,stad:()=>PREF.stadium,time:()=>PREF.daytime,ball:()=>PREF.ballDesign||"auto",diff:()=>o.diff};
  const card=(g,k,title,desc,sw,th)=>`<button type="button" class="pw-card${th?" th":""}"${th?` style="--th:url(${th})"`:""} data-g="${g}" data-k="${k}" aria-pressed="${val[g]()===k}">${sw?`<i class="pw-sw sw-${sw}"></i>`:""}<b>${title}</b><span>${desc}</span></button>`;
  const grp=(t,inner,cls)=>`<div class="pw-grp"><h3>${t}</h3><div class="pw-cards ${cls||""}">${inner}</div></div>`;
  const label={kit:()=>(o.kit||kDef())==="away"?"Alternativo":"Principal",kitR:()=>({auto:"Automático",home:"Principal",away:"Alternativo"})[o.kitR||"auto"],rules:()=>RULES[o.rules].n,var:()=>PREF.offsideVar===false?"Desligado":"Ligado",tac:()=>TACTICS[o.tac].n,form:()=>FORMS[o.form].n,stad:()=>STADIUM_INFO[PREF.stadium][0],time:()=>PREF.daytime==="day"?"Dia":"Noite",ball:()=>(BALLS.find(b=>b[0]===(PREF.ballDesign||"auto"))||BALLS[0])[1],diff:()=>DIFF[o.diff].n};
  const kcard=(g,k,title,desc,team,q)=>`<button type="button" class="pw-card" data-g="${g}" data-k="${k}" aria-pressed="${val[g]()===k}">${kg&&q?kg.kitSvg(kg.kitPara(team,q),64):""}<b>${title}</b><span>${desc}</span></button>`;
  const body={
    kit:()=>grp("O teu equipamento · "+TEAMS[o.L].n,kcard("kit","home","Principal",(kg?kg.kitInfo(o.L,"home"):""),o.L,"home")+kcard("kit","away","Alternativo",(kg?kg.kitInfo(o.L,"away"):""),o.L,"away"),"c2")+grp("Equipamento do adversário · "+TEAMS[o.R].n,kcard("kitR","auto","Automático","O adversário muda de equipamento se as cores forem parecidas com as tuas.",o.R,"")+kcard("kitR","home","Principal","",o.R,"home")+kcard("kitR","away","Alternativo","",o.R,"away"),"c3"),
    rules:()=>grp("Modo de jogo",Object.entries(RULES).map(([k,r])=>card("rules",k,r.n,r.d)).join(""),"c2")+grp("Fora de jogo e VAR",card("var","on","Ligado","Impedimentos assinalados e VAR a rever golos duvidosos.")+card("var","off","Desligado","Sem fora de jogo nem VAR."),"c2"),
    team:()=>grp("Tática",Object.entries(TACTICS).map(([k,t])=>card("tac",k,t.n,t.d)).join(""),"c3")+grp("Formação",Object.entries(FORMS).map(([k,f])=>card("form",k,f.n,f.d)).join(""),"c3"),
    stad:()=>grp("Estádio",Object.entries(STADIUM_INFO).map(([k,v])=>card("stad",k,v[0],v[1],"","modelos/miniaturas/"+k+"_"+PREF.daytime+".jpg")).join(""),"c3")+grp("Hora do jogo",card("time","night","Noite",TIMED.night,"night")+card("time","day","Dia",TIMED.day,"day"),"c2"),
    ball:()=>grp("Tipo de bola",BALLS.map(([k,n,d])=>card("ball",k,n,d,"","modelos/bolas/thumb_"+k+".png")).join(""),"c3")+(["girassol","diamante"].includes(cosm("ball").id)?`<p class="note">A bola especial escolhida na Carreira tem prioridade sobre esta escolha.</p>`:""),
    diff:()=>grp("Dificuldade",Object.entries(DIFF).map(([k,d])=>card("diff",k,d.n,DIFFD[k])).join(""),"c3"),
    go:()=>`<div class="pw-grp"><h3>Tudo pronto</h3><div class="pw-sum">${[["rules","Modo",0],["var","Fora de jogo e VAR",0],["tac","Tática",1],["form","Formação",1],["kit","O teu equipamento",2],["kitR","Equip. do adversário",2],["stad","Estádio",3],["time","Hora",3],["ball","Bola",4],["diff","Dificuldade",5]].map(([g,n,s])=>`<button type="button" class="pw-chip" data-jump="${s}"><small>${n}</small><b>${label[g]()}</b></button>`).join("")}</div><p class="note" style="text-align:center">Toca numa escolha para a mudar.</p></div>`
  };
  app.innerHTML=`<section class="screen pw">
   <div class="pw-top"><button class="back" id="qBack">${BACK}Voltar</button><div class="pw-title"><p class="eyebrow">${o.mode==="season"?`Jornada ${S.round+1} de ${S.fix.length}`:"Jogo rápido"}</p><h2>Antes do jogo</h2></div><button class="btn ghost small" id="pwSkip" type="button">Jogar já</button></div>
   <div class="pw-versus">
     <div class="pw-side">${crest(H,40)}${kitPreview(H,150)}<b>${TEAMS[H].n}</b><small>Casa</small></div>
     <div class="pw-mid"><span class="vs">VS</span><p class="muted">${STADIUM_INFO[PREF.stadium][0]}</p><p class="note">Estilo do ${R.n}: <b>${st.n}</b></p></div>
     <div class="pw-side">${crest(A,40)}${kitPreview(A,150)}<b>${TEAMS[A].n}</b><small>Fora</small></div>
   </div>
   <div class="pw-wiz">
     <div class="pw-steps" role="tablist">${STEPS.map(([k,n],i)=>`<button type="button" role="tab" class="pw-step" data-step="${i}"><i>${i+1}</i><span>${n}</span></button>`).join("")}</div>
     <div class="pw-body" id="pwBody"></div>
     <div class="pw-nav"><button class="btn ghost" id="pwPrev" type="button">Anterior</button><button class="btn" id="pwNext" type="button">Seguinte</button></div>
   </div>
  </section>`;
  const save=(g,k)=>{
    if(g==="rules"){o.rules=k;PREF.rules=k}else if(g==="var")PREF.offsideVar=k==="on";else if(g==="tac"){o.tac=k;PREF.tactic=k}else if(g==="form"){o.form=k;PREF.form=k}
    else if(g==="kit")o.kit=k;else if(g==="kitR")o.kitR=k;else if(g==="stad"){PREF.stadium=k;const mm=document.querySelector(".pw-mid .muted");if(mm)mm.textContent=STADIUM_INFO[k][0]}else if(g==="time")PREF.daytime=k;else if(g==="ball")PREF.ballDesign=k;else if(g==="diff"){o.diff=k;PREF.diff=k}
    savePrefs();
    if(g==="kit"||g==="kitR"){try{if(window.pwVs)window.pwVs.atualizar(o)}catch(e){}}
  };
  const draw=(dir)=>{
    const b=document.getElementById("pwBody");b.innerHTML=body[STEPS[step][0]]();b.dataset.dir=dir||0;b.classList.remove("in");void b.offsetWidth;b.classList.add("in");
    b.querySelectorAll(".pw-card").forEach(c=>c.onclick=()=>{save(c.dataset.g,c.dataset.k);b.querySelectorAll(`.pw-card[data-g="${c.dataset.g}"]`).forEach(x=>x.setAttribute("aria-pressed",x===c));try{sfx("ui")}catch(e){}});
    b.querySelectorAll("[data-jump]").forEach(c=>c.onclick=()=>{step=+c.dataset.jump;draw(-1)});
    app.querySelectorAll(".pw-step").forEach((s,i)=>{s.classList.toggle("on",i===step);s.classList.toggle("done",i<step);s.setAttribute("aria-selected",i===step)});
    const last=step===STEPS.length-1;
    document.getElementById("pwPrev").style.visibility=step?"visible":"hidden";
    const nx=document.getElementById("pwNext")||document.getElementById("qGo");nx.textContent=last?"Entrar em campo":"Seguinte";nx.id=last?"qGo":"pwNext";
    nx.onclick=last?()=>{ac();(window.launchPre||launch)(o)}:()=>{step++;draw(1)};
  };
  app.querySelectorAll(".pw-step").forEach(s=>s.onclick=()=>{const n=+s.dataset.step;draw(n>=step?1:-1,step=n)});
  on("pwPrev",()=>{if(step){step--;draw(-1)}});
  on("qBack",()=>o.mode==="season"?showHub():showPick("quick2",o.L));
  on("pwSkip",()=>{ac();(window.launchPre||launch)(o)});
  draw(0);
  window.scrollTo(0,0);
  try{window.pwVs=(window.G94&&G94.versus3D)?G94.versus3D(app.querySelector(".pw-versus"),o):null}catch(e){window.pwVs=null}
}

function showHub(){
  leaveMatch();
  if(!S){showMenu();return}
  finalizeSeason();
  const t=TEAMS[S.my],tab=sortedTable(),pos=tab.findIndex(r=>r.id===S.my)+1,me=S.table[S.my],done=seasonDone(),N=S.fix.length;
  let main;
  if(done){
    const champ=tab[0].id;
    Pop.seasonEnd(champ===S.my,t.n,pos,me.Pts,TEAMS[champ].n);main=`<div class="champ"><p class="eyebrow">Época terminada</p><h2>${champ===S.my?`Campeões! O ${t.n} ganhou a Girabola.`:`${TEAMS[champ].n} é campeão.`}</h2><p class="muted">O ${t.n} acabou em ${pos}º lugar com ${me.Pts} pontos. A época ficou registada no histórico da carreira.</p><div class="row"><button class="btn" id="hNew">Nova época</button><button class="btn ghost" id="hCar">Ver carreira</button></div></div>`;
  }else{
    const [h,a]=myFixture(),leg=S.legs===2?(S.round<15?" · 1.ª volta":" · 2.ª volta"):"";
    main=`<div class="panel"><p class="eyebrow">Jornada ${S.round+1} de ${N}${leg}</p>
      <div class="versus"><div class="side">${crest(h,54)}<b>${TEAMS[h].n}</b><small>Casa · Força ${TEAMS[h].r}</small></div><span class="vs">VS</span><div class="side">${crest(a,54)}<b>${TEAMS[a].n}</b><small>Fora · Força ${TEAMS[a].r}</small></div></div>
      <div class="row" style="justify-content:center"><button class="btn" id="hPlay">Jogar</button><button class="btn ghost" id="hSim">Simular resultado</button></div></div>`;
  }
  const last=S.last?`<div class="panel"><p class="panel-title">Resultados da jornada ${S.last.round+1}</p><div class="results">${S.last.res.map(([h,a,gh,ga])=>`<div class="res ${h===S.my||a===S.my?"mine":""}"><span>${TEAMS[h].n}</span><b>${gh} – ${ga}</b><span>${TEAMS[a].n}</span></div>`).join("")}</div></div>`:`<div class="panel"><p class="panel-title">Primeira jornada</p><p class="muted">Os resultados das outras equipas aparecem aqui depois de cada jornada.</p></div>`;
  app.innerHTML=`<section class="screen">
   <button class="back" id="hBack">${BACK}Menu</button>
   ${notices()}
   <div class="hub-head"><div class="hub-team">${crest(S.my,48)}<div style="min-width:0"><p class="eyebrow">A tua equipa · ${S.legs===2?"duas voltas":"uma volta"}</p><h2>${t.n}</h2></div></div>
     <div class="stats"><div class="stat"><b>${me.P?pos+"º":"–"}</b><span>Lugar</span></div><div class="stat"><b>${me.Pts}</b><span>Pontos</span></div><div class="stat"><b>${me.W}-${me.D}-${me.L}</b><span>V-E-D</span></div></div></div>
   ${main}
   <div class="cols"><div class="stack"><p class="panel-title">Classificação</p><div class="tablewrap"><table class="lt"><thead><tr><th>#</th><th>Equipa</th><th>J</th><th>V</th><th>E</th><th>D</th><th>GM</th><th>GS</th><th>DG</th><th>Pts</th></tr></thead><tbody>
     ${tab.map((r,i)=>`<tr class="${r.id===S.my?"me":""}"><td>${i+1}</td><td class="tm">${crest(r.id,16)}${TEAMS[r.id].n}</td><td>${r.P}</td><td>${r.W}</td><td>${r.D}</td><td>${r.L}</td><td>${r.F}</td><td>${r.A}</td><td>${r.F-r.A>0?"+":""}${r.F-r.A}</td><td class="pts">${r.Pts}</td></tr>`).join("")}
   </tbody></table></div></div>${last}</div>
   <div class="panel"><p class="panel-title">Objetivo da época</p><p>${t.r>=78?"Conquistar o título":t.r>=70?"Terminar nos cinco primeiros":"Terminar na primeira metade da tabela"} · posição atual: ${pos}º.</p></div>
   <p class="note">Equipas da Girabola 2026/27. A força de cada equipa, os estilos de jogo e as cores são atribuídos pelo jogo, não são dados oficiais. A classificação começa do zero e os outros jogos são simulados.</p>
  </section>`;
  on("hBack",showMenu);on("hNew",()=>showPick("season"));on("hCar",showCareer);
  on("hPlay",()=>{const [h,a]=myFixture();showPrematch({L:S.my,R:h===S.my?a:h,homeLeft:h===S.my,mode:"season"})});
  on("hSim",()=>{const [h0,a0]=myFixture();Pop.confirm({icon:"swap",title:"Simular o jogo?",html:`<p><b>${TEAMS[h0].n}</b> × <b>${TEAMS[a0].n}</b> é decidido automaticamente. Ganhas só 40% do XP e não podes repetir o jogo.</p>`,yes:"Simular",no:"Prefiro jogar",onYes:()=>{const [h,a]=myFixture(),[gh,ga]=simScore(h,a);completeRound({gh,ga},false);const mine=h===S.my,my=mine?gh:ga,op=mine?ga:gh;showHub();setTimeout(()=>Pop.open({id:"simres",kind:my>op?"celebrate":"info",icon:my>op?"trophy":"info",eyebrow:"Resultado simulado",title:my>op?"Vitória!":my<op?"Derrota":"Empate",confetti:my>op?60:0,html:`<div class="pop-kv"><div><b>${gh} – ${ga}</b><span>${TEAMS[h].s} × ${TEAMS[a].s}</span></div></div><p>${TEAMS[h].n} × ${TEAMS[a].n}</p>`,actions:[{label:"Continuar",kind:"gold"}]}),350)}})});
  window.scrollTo(0,0);
}

function showCareer(){
  leaveMatch();
  const lv=level(),into=C.xp%150,titles=Object.entries(C.titles).filter(([,v])=>v>0).sort((a,b)=>b[1]-a[1]);
  const mine=C.seasons.filter(s=>s.pos===1).length;
  const cos=k=>`<div class="opt"><span class="panel-title">${{ball:"Bola",marker:"Marcador do jogador",confetti:"Festejo de golo"}[k]}</span><div class="chips">${COSM[k].map(c=>`<button class="chip" data-cos="${k}" data-id="${c.id}" aria-pressed="${C.cos[k]===c.id}" ${lv<c.lvl?`data-locked="${c.lvl}" aria-disabled="true"`:""}>${c.c?`<i style="background:${c.c}"></i>`:""}${c.n}${lv<c.lvl?` · nível ${c.lvl}`:""}</button>`).join("")}</div></div>`;
  app.innerHTML=`<section class="screen">
   <button class="back" id="cBack">${BACK}Menu</button>
   <div><p class="eyebrow">Carreira</p><h2>Nível ${lv}</h2></div>
   <div class="panel"><div class="xpbar" aria-label="Progresso para o nível seguinte"><i style="width:${Math.round(into/150*100)}%"></i></div><p class="muted">${into}/150 XP para o nível ${lv+1}. Ganhas XP em cada jogo (mais com vitórias e golos) e no fim de cada época. As recompensas são apenas visuais.</p>
     <div class="stats"><div class="stat"><b>${C.played}</b><span>Jogos</span></div><div class="stat"><b>${C.W}-${C.D}-${C.L}</b><span>V-E-D</span></div><div class="stat"><b>${C.goals}</b><span>Golos</span></div><div class="stat"><b>${mine}</b><span>Títulos teus</span></div></div></div>
   <div class="panel"><p class="panel-title">Recompensas</p>${cos("ball")}${cos("marker")}${cos("confetti")}</div>
   <div class="panel"><p class="panel-title">Campeões nas tuas épocas</p>${titles.length?`<div class="titles">${titles.map(([i,v])=>`<div>${crest(+i,20)}${TEAMS[i].n} <b>${v}</b></div>`).join("")}</div>`:`<p class="muted">Ainda não terminaste nenhuma época.</p>`}</div>
   <div class="panel"><p class="panel-title">Histórico de épocas</p>${C.seasons.length?`<div class="tablewrap"><table><thead><tr><th style="text-align:left">Terminada</th><th style="text-align:left">Equipa</th><th>Jornadas</th><th>Lugar</th><th>Pts</th><th style="text-align:left">Campeão</th></tr></thead><tbody>${C.seasons.slice().reverse().map(s=>`<tr><td style="text-align:left">${s.end?new Date(s.end).toLocaleDateString("pt-PT"):"–"}</td><td class="tm">${crest(s.team,16)}${TEAMS[s.team].n}</td><td>${s.legs*15}</td><td>${s.pos}º</td><td>${s.pts}</td><td style="text-align:left">${TEAMS[s.champ].n}</td></tr>`).join("")}</tbody></table></div>`:`<p class="muted">As épocas terminadas aparecem aqui.</p>`}</div>
  </section>`;
  on("cBack",showMenu);
  app.querySelectorAll("[data-cos]").forEach(b=>b.onclick=()=>{if(b.dataset.locked){const need=+b.dataset.locked,xp=(need-1)*150-C.xp;Pop.info({icon:"level",eyebrow:"Bloqueado",title:b.textContent.split(" · ")[0],html:`<p>Desbloqueia no <b>nível ${need}</b>. Faltam cerca de <b>${Math.max(0,xp)} XP</b>: ganhas XP em cada jogo (mais com vitórias e golos) e no fim de cada época.</p>`,ok:"Percebi",cancel:"Jogar agora",onCancel:()=>showPick("quick1")});return}C.cos[b.dataset.cos]=b.dataset.id;saveCareer();showCareer();setTimeout(()=>Pop.toast("Recompensa aplicada"),60)});
  window.scrollTo(0,0);
}

function showOptions(msg){
  if(typeof msg!=="string")msg=undefined;   // um clique passa o evento como 1.º argumento: não é uma mensagem
  leaveMatch();REBIND=null;
  app.innerHTML=`<section class="screen">
   <button class="back" id="oBack">${BACK}Menu</button>
   <div><p class="eyebrow">Opções</p><h2>Controlos e jogo</h2></div>
   ${msg?`<div class="notice info">${msg}</div>`:""}
   <div class="panel"><p class="panel-title">Teclado</p><p class="note">Carrega numa tecla para a alterar e prime a nova tecla. Esc cancela. Se a tecla já estiver noutra ação, sai de lá.</p>
     <div class="tablewrap" style="background:none"><table class="keys-table"><thead><tr><th>Ação</th><th>Tecla principal</th><th>Alternativa</th></tr></thead><tbody>
     ${ACTIONS.map(([a,l])=>`<tr><td>${l}</td>${[0,1].map(s=>`<td><button class="keybtn" data-a="${a}" data-s="${s}">${kn(PREF.keys[a][s])}</button></td>`).join("")}</tr>`).join("")}
     </tbody></table></div>
     <div class="row"><button class="btn ghost small" id="kReset">Repor teclas predefinidas</button></div></div>
   <div class="panel"><p class="panel-title">Câmara</p>${segHTML("cam",[["tv","Transmissão"],["top","Vista de cima"]],PREF.camera)}<p class="note">Transmissão: câmara inclinada que segue a bola, com radar no canto. Vista de cima: o campo inteiro de uma vez, mais leve para telemóveis antigos.</p><div id="zoomOpt"></div></div>
   <div class="panel"><p class="panel-title">Troca de jogador</p>${segHTML("asw",[["assist","Assistida"],["manual","Manual"]],PREF.autoSwitch)}
     <p class="note">Assistida: troca sozinha só quando o teu jogador fica muito longe da bola, no máximo uma vez a cada 1,2 s. Manual: só trocas com a tecla ou o botão Trocar. Em ambos os modos passas a controlar quem ganha a bola e quem vai receber o teu passe.</p></div>
   <div class="panel"><p class="panel-title">Jogo</p>
     <label class="toggle"><span>Reduzir efeitos visuais (sem tremor, câmara lenta, flashes nem animações nas bancadas)</span><input type="checkbox" id="oFx" ${PREF.reduceFx?"checked":""}></label>
     <label class="toggle"><span>Apresentação cinematográfica: mostrar a entrada das equipas antes do jogo (Esc salta)</span><input type="checkbox" id="oIntro" ${PREF.intro!==false?"checked":""}></label>
     <label class="toggle"><span>Mostrar replay dos golos</span><input type="checkbox" id="oRep" ${PREF.replays?"checked":""}></label>
     <label class="toggle"><span>Fadiga: correr e fazer sprint cansa os jogadores (menos aceleração e mais erros)</span><input type="checkbox" id="oFat" ${PREF.fatigue!==false?"checked":""}></label>
     <label class="toggle"><span>Remate com temporização: carrega uma segunda vez no momento do contacto para rematar com mais precisão</span><input type="checkbox" id="oTim" ${PREF.shotTiming?"checked":""}></label>
     <div class="opt"><span class="panel-title">Janela de temporização</span>${segHTML("tim",[["60","Apertada"],["90","Normal"],["140","Larga"]],String(PREF.timingWin||90))}</div>
     <label class="toggle"><span>Som da multidão e batuque nas bancadas</span><input type="checkbox" id="oSnd" ${PREF.sound?"checked":""}></label>
     <div class="row"><button class="btn ghost small" id="oTut">Repetir tutorial</button></div></div>
  </section>`;
  const panel=document.createElement("div");panel.className="panel";panel.innerHTML=`<p class="panel-title">Precisão e desempenho</p><p class="note">Sprint + Passe faz um passe em profundidade no modo assistido. A posse inclui passes em trânsito; bolas soltas são excluídas.</p><p>Assistência de passe</p>${segHTML("passAssist",[["assist","Assistido"],["manual","Direcional"]],PREF.passAssist)}<p>Remate</p>${segHTML("shotStyle",[["power","Potente"],["placed","Colocado"]],PREF.shotStyle)}<p>Qualidade de resolução</p>${segHTML("quality",[["low","Baixa"],["medium","Média"],["high","Alta"]],PREF.quality)}<p>Bola</p>${segHTML("ballDesign",[["auto","Auto"],["rubro_negra","Rubro-negra"],["angola","Angola"],["azul","Azul"],["classica","Clássica"],["verde","Verde"]],PREF.ballDesign||"auto")}<p>Adeptos nas bancadas</p>${segHTML("crowd",[["auto","Auto"],["off","Sem"],["low","Poucos"],["med","Muitos"],["high","Cheio"]],PREF.crowd||"auto")}<p>Tamanho dos botões táteis</p>${segHTML("touchScale",[["1","Normal"],["1.15","Grande"],["1.3","Maior"]],String(PREF.touchScale))}`;app.querySelector("section").appendChild(panel);
  for(const k of ["passAssist","shotStyle","quality","crowd","ballDesign"])bindSeg(k,v=>{PREF[k]=v;savePrefs()});bindSeg("touchScale",v=>{PREF.touchScale=+v;savePrefs()});
  on("oBack",showMenu);on("oTut",()=>{ac();startTutorial()});
  on("kReset",()=>Pop.confirm({danger:true,icon:"key",title:"Repor as teclas?",text:"Todas as teclas voltam às predefinidas (WASD, X, Espaço, C, Shift, P).",yes:"Repor teclas",no:"Manter",onYes:()=>{PREF.keys=JSON.parse(JSON.stringify(DEFAULT_KEYS));savePrefs();buildCodeMap();showOptions("Teclas repostas.")}}));
  bindSeg("asw",k=>{PREF.autoSwitch=k;savePrefs()});
  bindSeg("cam",k=>{PREF.camera=k;savePrefs()});
  document.getElementById("oFx").onchange=e=>{PREF.reduceFx=e.target.checked;savePrefs()};
  document.getElementById("oRep").onchange=e=>{PREF.replays=e.target.checked;savePrefs()};
  document.getElementById("oSnd").onchange=e=>{PREF.sound=e.target.checked;savePrefs()};
  document.getElementById("oFat").onchange=e=>{PREF.fatigue=e.target.checked;savePrefs()};
  document.getElementById("oIntro").onchange=e=>{PREF.intro=e.target.checked;savePrefs()};
  document.getElementById("oTim").onchange=e=>{PREF.shotTiming=e.target.checked;savePrefs()};
  bindSeg("tim",k=>{PREF.timingWin=+k;savePrefs()});
  app.querySelectorAll(".keybtn").forEach(b=>b.onclick=()=>{
    app.querySelectorAll(".keybtn.wait").forEach(x=>{x.classList.remove("wait");x.textContent=kn(PREF.keys[x.dataset.a][+x.dataset.s])});
    REBIND={a:b.dataset.a,s:+b.dataset.s};b.classList.add("wait");b.textContent="Prime uma tecla";Pop.keyWait(ACTIONS.find(x=>x[0]===b.dataset.a)[1],+b.dataset.s,()=>{REBIND=null;showOptions()});
  });
  window.scrollTo(0,0);
}
function finishRebind(code){
  Pop.closeKey();const r=REBIND;REBIND=null;if(!r)return;
  if(code==="Escape"&&!(r.a==="pause")){showOptions();return}
  let moved="";
  for(const a in PREF.keys)for(let s=0;s<2;s++)if(PREF.keys[a][s]===code&&!(a===r.a&&s===r.s)){PREF.keys[a][s]="";moved=ACTIONS.find(x=>x[0]===a)[1]}
  PREF.keys[r.a][r.s]=code;savePrefs();buildCodeMap();
  const empty=ACTIONS.filter(([a])=>!PREF.keys[a][0]&&!PREF.keys[a][1]).map(x=>x[1]);
  showOptions(`${kn(code)} ficou em «${ACTIONS.find(x=>x[0]===r.a)[1]}».${moved?` Saiu de «${moved}».`:""}${empty.length?` Atenção: sem tecla em ${empty.map(x=>`«${x}»`).join(", ")}.`:""}`);
}

function showData(state){
  leaveMatch();state=state&&typeof state==="object"&&!(state instanceof Event)?state:{};
  const json=S?JSON.stringify({app:"girabola-craque",kind:"epoca",v:2,exportedAt:new Date().toISOString(),season:S},null,1):"";
  app.innerHTML=`<section class="screen">
   <button class="back" id="dBack">${BACK}Voltar</button>
   <div><p class="eyebrow">Dados da época</p><h2>Exportar ou importar</h2></div>
   ${notices()}
   <div class="panel"><p class="panel-title">Exportar</p>
     ${S?`<p class="muted">${TEAMS[S.my].n} · jornada ${Math.min(S.round+1,S.fix.length)} de ${S.fix.length}${seasonDone()?" · terminada":""}</p><textarea id="exTxt" readonly aria-label="Época em JSON">${json.replace(/</g,"&lt;")}</textarea>
     <div class="row"><button class="btn small" id="exCopy">Copiar</button><button class="btn ghost small" id="exDl">Descarregar ficheiro .json</button><span class="note" id="exMsg"></span></div>`:`<p class="muted">Ainda não há nenhuma época para exportar.</p>`}
   </div>
   <div class="panel"><p class="panel-title">Importar</p>
     <p class="note">Escolhe um ficheiro exportado pelo Girabola 94 ou cola o texto JSON. O jogo verifica os dados antes de substituir alguma coisa.</p>
     <input type="file" id="imFile" accept=".json,application/json">
     <textarea id="imTxt" placeholder="Cola aqui o JSON da época" aria-label="JSON a importar"></textarea>
     <div class="row"><button class="btn small" id="imCheck">Verificar</button></div>
     <div id="imOut">${state.out||""}</div>
   </div>
  </section>`;
  const full=document.createElement("button");full.className="btn ghost";full.textContent="Descarregar backup completo";app.querySelector("section").appendChild(full);full.onclick=()=>{const data=JSON.stringify({app:"girabola-craque",kind:"backup",v:3,season:S,career:C,prefs:PREF},null,2),a=document.createElement("a"),url=URL.createObjectURL(new Blob([data],{type:"application/json"}));a.href=url;a.download="girabola-backup-completo.json";a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
  on("dBack",()=>S&&!SEASON_BAD?showHub():showMenu());
  on("exCopy",()=>{const ta=document.getElementById("exTxt"),m=document.getElementById("exMsg");
    const fb=()=>{ta.focus();ta.select();m.textContent="Texto selecionado. Copia com Ctrl+C ou o menu do telemóvel."};
    try{navigator.clipboard.writeText(ta.value).then(()=>{m.textContent="Copiado.";Pop.toast("Época copiada para a área de transferência")},fb)}catch(e){fb()}});
  on("exDl",()=>{try{const a=document.createElement("a");a.href=URL.createObjectURL(new Blob([json],{type:"application/json"}));a.download=`girabola-craque-${TEAMS[S.my].s}-j${S.round}.json`;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},500);document.getElementById("exMsg").textContent="Se o ficheiro não descarregar, usa Copiar."}catch(e){document.getElementById("exMsg").textContent="Não foi possível descarregar. Usa Copiar."}});
  document.getElementById("imFile").onchange=e=>{const f=e.target.files&&e.target.files[0];if(!f)return;if(f.size>2e6){importResult("O ficheiro é demasiado grande para ser uma época.");return}
    const r=new FileReader();r.onload=()=>{document.getElementById("imTxt").value=String(r.result);checkImport()};r.onerror=()=>importResult("Não foi possível ler o ficheiro.");r.readAsText(f)};
  on("imCheck",checkImport);
  window.scrollTo(0,0);
}
function importResult(html,ok){document.getElementById("imOut").innerHTML=`<div class="notice ${ok?"info":""}">${html}</div>`}
function checkImport(){
  const txt=document.getElementById("imTxt").value.trim();
  if(!txt){importResult("Cola o JSON ou escolhe um ficheiro primeiro.");return}
  if(txt.length>2e6){importResult("O texto é demasiado grande para ser uma época.");return}
  const o=parseJSON(txt);if(o===null){importResult("O texto não é JSON válido.");return}
  if(o&&o.app==="girabola-craque"&&o.kind==="backup"){checkFullBackup(o);return}
  const src=o&&typeof o==="object"&&o.season&&o.app==="girabola-craque"?o.season:o;
  const v=validateSeason(src);
  if(!v.ok){importResult(`Não foi importado. ${v.err}`);return}
  const n=v.season,cur=S&&!seasonDone();
  importResult(`<p>Época válida: <b>${TEAMS[n.my].n}</b>, jornada ${Math.min(n.round+1,n.fix.length)} de ${n.fix.length}${n.round>=n.fix.length?" (terminada)":""}.</p>
    ${S?`<p style="margin-top:6px">Isto substitui a época atual (${TEAMS[S.my].n}, jornada ${Math.min(S.round+1,S.fix.length)} de ${S.fix.length}${cur?"":", terminada"}).</p>`:""}
    <div class="row" style="margin-top:10px"><button class="btn ${S?"danger":""} small" id="imYes">${S?"Substituir época":"Importar época"}</button><button class="btn ghost small" id="imNo">Cancelar</button></div>`,true);
  on("imYes",()=>Pop.confirm({danger:!!S,title:S?"Substituir a época atual?":"Importar época?",text:S?`A época em curso (<b>${TEAMS[S.my].n}</b>, jornada ${Math.min(S.round+1,S.fix.length)} de ${S.fix.length}) será substituída por <b>${TEAMS[n.my].n}</b>.`:`Vais começar com o <b>${TEAMS[n.my].n}</b> na jornada ${Math.min(n.round+1,n.fix.length)}.`,yes:S?"Substituir":"Importar",onYes:()=>{if(C.seasons.some(x=>x.id===n.id))n.recorded=true;S=n;SEASON_BAD=false;saveSeason();showHub();Pop.toast("Época importada")}}));
  on("imNo",()=>{document.getElementById("imOut").innerHTML=""});
}



let CUP=null;
function showCup(){
  leaveMatch();app.innerHTML=`<section class="screen"><button class="back" id="cupBack">${BACK}Menu</button><h2>Taça Girabola</h2><p class="note">Competição fictícia de quatro rondas. Empates são decididos por penáltis. A taça atual é mantida nesta sessão.</p>${CUP?`<p>${TEAMS[CUP.my].n} · ${["Oitavos de final","Quartos de final","Meias-finais","Final"][CUP.round]}</p><button class="btn" id="cupContinue">Continuar taça</button>`:""}<div class="grid">${TEAMS.slice(0,BASE_N).map((t,i)=>`<button class="team" data-cup="${i}">${kitPreview(i,86)}<b>${t.n}</b></button>`).join("")}</div></section>`;
  on("cupBack",showMenu);on("cupContinue",playCup);
  app.querySelectorAll("[data-cup]").forEach(b=>b.onclick=()=>{const ci=+b.dataset.cup,go=()=>{CUP={my:ci,round:0,pool:TEAMS.slice(0,BASE_N).map((_,i)=>i)};playCup()};Pop.team(ci,{eyebrow:"Taça Girabola",noGoal:false,yes:CUP?"Recomeçar a taça →":"Começar a taça →",warn:CUP?"Já tens uma taça em curso ("+TEAMS[CUP.my].n+"). Escolher outra equipa apaga-a.":"",onYes:go})});
}
function playCup(){const opp=CUP.pool.find(i=>i!==CUP.my);ac();launch({L:CUP.my,R:opp,homeLeft:true,mode:"cup",diff:PREF.diff,rules:PREF.rules,tac:PREF.tactic,form:PREF.form});G.msg=["Oitavos de final","Quartos de final","Meias-finais","Final"][CUP.round]}
function advanceCup(won){
  if(!CUP)return;const name=TEAMS[CUP.my].n;
  if(!won||CUP.round===3){showOverlay(`<div class="card"><h2>${won?"Vencedor da Taça!":"Eliminado da Taça"}</h2><p>${name}</p><button class="btn" id="cupFinish">Menu</button></div>`);CUP=null;on("cupFinish",()=>{leaveMatch();showMenu()});return}
  const opp=G.o.R,rest=CUP.pool.filter(i=>i!==CUP.my&&i!==opp),w=[CUP.my];for(let i=0;i<rest.length;i+=2){const [a,b]=[rest[i],rest[i+1]],[ga,gb]=simScore(a,b);w.push(ga===gb?(Math.random()<.5?a:b):ga>gb?a:b)}CUP.pool=w;CUP.round++;
  showOverlay(`<div class="card"><h2>Qualificado!</h2><p>Próxima ronda: ${["Oitavos","Quartos","Meias-finais","Final"][CUP.round]}</p><button class="btn" id="cupNext">Continuar</button><button class="btn ghost" id="cupExit">Menu</button></div>`);on("cupNext",()=>{leaveMatch();playCup()});on("cupExit",()=>{leaveMatch();showMenu()});
}
function showPenalties(done){
  let n=0,a=0,b=0,log="";G.paused=true;releaseAll();
  const draw=()=>{showOverlay(`<div class="card"><p class="eyebrow">Desempate por penáltis</p><h2>${a} – ${b}</h2><p>${n<5?"Série de cinco":"Morte súbita"} · escolhe onde rematar</p><p class="note">Rematar para um canto é mais difícil para o guarda-redes, mas tem maior risco de sair ao lado.</p><div class="row"><button class="btn" data-pen="0">Esquerda</button><button class="btn" data-pen="1">Centro</button><button class="btn" data-pen="2">Direita</button></div><p aria-live="polite">${log}</p></div>`);document.querySelectorAll("[data-pen]").forEach(el=>el.onclick=()=>{const target=+el.dataset.pen,gk=Math.floor(Math.random()*3),goal=Math.random()<(target===1?.98:.9)&&(gk!==target||Math.random()<.25),their=Math.random()<.72;a+=goal?1:0;b+=their?1:0;n++;log=(goal?"Marcaste.":"Não marcaste.")+" "+(their?"O adversário marcou.":"O adversário falhou.");if(n>=5&&a!==b){G.paused=false;done(a>b)}else draw()})};draw();
}

function checkFullBackup(o){
  if(o.v!==3||!o.career||!o.prefs){importResult("Backup incompleto ou versão não suportada.");return}
  const v=o.season===null?{ok:true,season:null}:validateSeason(o.season);if(!v.ok){importResult(v.err);return}
  const r=o.career;
  if(["xp","played","W","D","L","goals"].some(k=>!isInt(r[k],0,1e9))||r.W+r.D+r.L!==r.played||!Array.isArray(r.seasons)||r.seasons.length>100||!r.titles||typeof r.titles!=="object"||!r.cos||typeof r.cos!=="object"){importResult("Carreira inválida.");return}
  if(r.seasons.some(x=>!x||typeof x.id!=="string"||!/^[a-z0-9]{4,24}$/i.test(x.id)||!isInt(x.team,0,15)||!isInt(x.pos,1,16)||!isInt(x.pts,0,999)||![1,2].includes(x.legs))||new Set(r.seasons.map(x=>x.id)).size!==r.seasons.length){importResult("Histórico inválido.");return}
  if(Object.entries(r.titles).some(([k,v])=>!/^([0-9]|1[0-5])$/.test(k)||!isInt(v,0,9999))||Object.keys(COSM).some(k=>!COSM[k].some(c=>c.id===r.cos[k]))){importResult("Títulos ou cosméticos inválidos.");return}
  if(!o.prefs||typeof o.prefs!=="object"||Array.isArray(o.prefs)||!o.prefs.keys||Object.keys(DEFAULT_KEYS).some(k=>!Array.isArray(o.prefs.keys[k])||o.prefs.keys[k].length!==2||o.prefs.keys[k].some(c=>typeof c!=="string"||!/^([A-Za-z][A-Za-z0-9]{0,39})?$/.test(c)))){importResult("Opções inválidas.");return}
  importResult('<p>Backup válido. Substituir época, carreira e opções atuais?</p><button class="btn danger" id="fullYes">Restaurar backup</button><button class="btn ghost" id="fullNo">Cancelar</button>',true);
  on("fullNo",()=>document.getElementById("imOut").innerHTML="");
  on("fullYes",()=>{
    const entries=[[K.season,JSON.stringify(v.season)],[K.career,JSON.stringify(r)],[K.prefs,JSON.stringify(o.prefs)]],old=entries.map(([k])=>sGet(k));
    for(let i=0;i<entries.length;i++)if(!sSet(...entries[i])){for(let j=0;j<i;j++){try{old[j]===null?localStorage.removeItem(entries[j][0]):localStorage.setItem(entries[j][0],old[j])}catch(e){}}importResult("Falha na gravação. Os dados em memória foram preservados.");return}
    S=v.season;C=loadCareer();PREF=loadPrefs();buildCodeMap();showMenu();
  });
}

/* Ganchos de teste (não afetam o jogo) */
window.__gc={get G(){return G},get S(){return S},get C(){return C},get PREF(){return PREF},step:n=>{for(let i=0;i<n&&G;i++){readInput();step()}},input,setPause,startSecondHalf,endReplay};
/* Som sintetizado de bancada: murmúrio, vozes e aplausos; não é uma gravação. */
function crowdEvent(kind){if(!G)return;G.crowdPulse=Math.max(G.crowdPulse||0,kind==='goal'?1:kind==='save'?.65:.4);G.crowdEvent=kind;}
ambientStart=function(){if(!PREF.sound||!ac()||AMB)return;try{const s=AC.createBufferSource(),f=AC.createBiquadFilter(),g=AC.createGain();s.buffer=NOISE;s.loop=true;f.type='bandpass';f.frequency.value=650;f.Q.value=.5;g.gain.value=.035;s.connect(f);f.connect(g);g.connect(AC.destination);s.start();AMB={s,g,f,voices:[],lastClap:0};for(let i=0;i<6;i++){const o=AC.createOscillator(),v=AC.createGain();o.type='triangle';o.frequency.value=145+i*29;v.gain.value=.002;o.connect(v);v.connect(g);o.start();AMB.voices.push({o,v})}nextBeat=AC.currentTime+.3}catch(e){ambientStop()}};
ambientStop=function(){if(!AMB)return;try{AMB.s.stop();for(const v of AMB.voices||[]){v.o.stop();v.o.disconnect();v.v.disconnect()}AMB.s.disconnect();AMB.g.disconnect();AMB.f?.disconnect()}catch(e){}AMB=null};
function crowdUpdate(dt){
 if(!G)return;G.crowdPulse=Math.max(0,(G.crowdPulse||0)-dt*.18);if(!AMB||!AC)return;
 const t=AC.currentTime,playing=!G.paused&&!G.ended,ball=G.ball;
 const near=G.state==='play'&&ball?clamp(1-Math.min(Math.abs(ball.x-X0),Math.abs(ball.x-X1))/180,0,1)*clamp(1-Math.abs(ball.y-H/2)/180,0,1):0;
 const level=playing?clamp(near*.35+(G.crowdPulse||0),0,1):0;
 AMB.g.gain.setTargetAtTime(playing?.035+level*.22:0,t,.22);AMB.f.frequency.setTargetAtTime(550+level*850,t,.3);
 for(let i=0;i<AMB.voices.length;i++){const {o,v}=AMB.voices[i];o.frequency.setTargetAtTime(145+i*29+Math.sin(t*2+i)*15+level*35,t,.1);v.gain.setTargetAtTime(.012+level*.04,t,.12)}
 if(playing&&level>.35&&t-AMB.lastClap>.16){AMB.lastClap=t;try{const s=AC.createBufferSource(),f=AC.createBiquadFilter(),g=AC.createGain();s.buffer=NOISE;f.type='highpass';f.frequency.value=1400;s.connect(f);f.connect(g);g.connect(AC.destination);env(g,t,.002,.035*level,.055);s.start(t);s.stop(t+.07);s.onended=()=>{s.disconnect();f.disconnect();g.disconnect()}}catch(e){}}
}
/* Arbitragem arcade: faltas por contacto perigoso, cartões e livres. */
function discipline(){if(!G.laws)G.laws=[0,1].map(()=>({fouls:0,yellow:0,red:0,corners:0,offsides:0}));return G.laws}
function callFoul(offender,victim,severe=false,info){
 if(!G||G.tut||G.state!=='play'||offender.off)return false;
 const laws=discipline(),x=victim.x,y=victim.y,og=sd(offender.team)===0?X0:X1,dg=Math.abs(x-og);
 offender.dash=0;offender.tackling=false;offender.foulCd=2;victim.stun=0;laws[offender.team].fouls++;
 offender.fouls=(offender.fouls||0)+1;let card='',cc=null;
 const field=G.players.filter(q=>!q.off&&q.team===offender.team&&q.role!=='GK').length;
 const covered=G.players.some(q=>!q.off&&q.team===offender.team&&q!==offender&&q.role!=="GK"&&Math.abs(q.x-og)<dg-6&&Math.abs(q.y-y)<100);
 const dogso=severe&&dg<250&&Math.abs(y-H/2)<170&&!covered;
 const canRed=offender.role!=='GK'&&field>3;
 const brutal=!!(info&&info.slide&&info.rel>1.6&&(info.behind||info.al<.3));      // carrinho por trás/de lado a grande velocidade
 if(canRed&&(dogso||brutal)){card=dogso?'Vermelho · ocasião de golo':'Vermelho direto';cc='red';offender.off=true;laws[offender.team].red++}
 else if(severe||(info&&info.slide&&info.rel>1.2)||offender.fouls>=3){offender.yellow=(offender.yellow||0)+1;laws[offender.team].yellow++;card='Amarelo';cc='yellow';
  if(offender.yellow>=2&&canRed){offender.off=true;laws[offender.team].red++;card='Vermelho · segundo amarelo';cc='red'}}
 if(offender.off&&G.ctrl===offender)setCtrl(nearestOf(0,G.ball,false,offender));
 const inBox=dg<140&&Math.abs(y-H/2)<160;
 /* lei da vantagem: a equipa lesada mantém a bola numa situação prometedora (a progredir, com espaço à frente) → o jogo segue até 2,5 s */
 const adv=!inBox&&cc!=='red'&&!G.adv&&G.ball.owner===victim&&!victim.off&&nxOf(victim.team,victim.x)>.45&&Math.hypot(victim.vx,victim.vy)>.6*victim.sp
   &&!G.players.some(q=>!q.off&&q.team!==victim.team&&q!==offender&&q.role!=='GK'&&Math.hypot(q.x-victim.x,q.y-victim.y)<70);
 if(adv){G.adv={team:victim.team,x:x,y:y,offender,victim,until:G.t+2.5};G.msg='Vantagem';G.msgSub=offender.name+(card?' · '+card:'')+' · segue o jogo';try{sfx('whistle')}catch(e){}
  G.refCard=cc?{color:cc==='red'?'#e63238':'#ffe13c',until:G.t+3}:null;
  if(cc)G.cardShow={color:cc,name:offender.name,num:offender.num,team:offender.team,text:card,until:performance.now()+3200,x:offender.x,y:offender.y};
  return true}
 if(inBox){startPenalty(victim.team,offender,victim);G.msg='Penálti';G.msgSub=offender.name+(card?' · '+card:'')+' · '+G.teams[victim.team].s}
 else{const fx=clamp(x,X0+12,X1-12),fy=clamp(y,Y0+12,Y1-12);if(window.fkInRange&&window.fkInRange(victim.team,fx,fy))window.startFK(victim.team,fx,fy);else startSetPiece('freekick',victim.team,fx,fy);G.msg=card||'Falta · livre';G.msgSub=offender.name+' · '+G.teams[victim.team].s}
 G.refCard=cc?{color:cc==='red'?'#e63238':'#ffe13c',until:G.t+3}:null;
 if(cc)G.cardShow={color:cc,name:offender.name,num:offender.num,team:offender.team,text:card,until:performance.now()+3200,x:offender.x,y:offender.y};
 return true;
}
function startPenalty(team,offender,victim,forced){
 const b=G.ball,gx=sd(team)===0?X1:X0,dir=sd(team)===0?1:-1,spotX=gx-dir*100;
 const gk=G.players.find(p=>p.team!==team&&p.role==='GK'&&!p.off);
 let taker=forced||G.players.find(p=>p.team===team&&!p.off&&p.role==='F'&&p!==offender)||(!victim.off?victim:null)||nearestOf(team,{x:spotX,y:H/2},false);
 G.state='pen';G.charging=false;G.charge=0;G.trail.length=0;G.hot=0;G.passTarget=null;G.setp=null;G.aim=null;
 b.owner=null;b.pend=null;b.vx=b.vy=0;b.x=spotX;b.y=H/2;b.lastTeam=team;b.last=taker;
 let k=0;
 for(const p of G.players){
  if(p.off)continue;
  p.vx=p.vy=p.dx=p.dy=0;p.stun=0;p.dash=0;p.tackling=false;p.dive=null;p.gkDown=0;p.gkJump=0;p.penPick=null;p.sprint=false;
  if(p===taker){p.x=spotX-dir*15;p.y=H/2;p.fx=dir;p.fy=0}
  else if(p===gk){p.x=gx-dir*7;p.y=H/2;p.fx=-dir;p.fy=0}
  else if(G.shoot){p.x=W/2+(k%2?40:-40);p.y=H/2+(k-3)*26;p.fx=dir;p.fy=0;k++}
  else{p.x=clamp(gx-dir*(170+(k%2)*24),X0+8,X1-8);p.y=clamp(H/2+(k%2?1:-1)*(120+Math.floor(k/2)*44),Y0+8,Y1-8);p.fx=-dir;p.fy=0;k++}
 }
 G.pen={team,taker,gk,gx,dir,t:0,aim:0,fired:false};
 if(team===0)setCtrl(taker);
 sfx('whistle',2);
}

const rulesStep=step;
step=function(){rulesStep();if(!G||G.paused)return;for(const p of G.players)p.foulCd=Math.max(0,(p.foulCd||0)-DT);advStep();refStep()};
/* resolução da vantagem: mantida a posse, segue o jogo; perdida a posse ou esgotado o tempo sem ela, volta-se à falta */
function advStep(){
 const A=G.adv;if(!A)return;
 if(G.state!=='play'){G.adv=null;return}
 const b=G.ball,o=b.owner,keep=(o&&o.team===A.team)||(!o&&b.lastTeam===A.team);
 if((o&&o.team!==A.team)||(G.t>=A.until&&!keep)){G.adv=null;G.advBack=(G.advBack||0)+1;startSetPiece('freekick',A.team,clamp(A.x,X0+12,X1-12),clamp(A.y,Y0+12,Y1-12));G.msg='Livre · sem vantagem';return}
 if(G.t>=A.until){G.adv=null;G.advOK=(G.advOK||0)+1;G.msg='';G.msgSub=''}
}
/* o árbitro procura a diagonal do jogo, fora da linha da bola e dos jogadores, com velocidade limitada; os assistentes acompanham a linha defensiva pela linha lateral */
function refStep(){
 const r=G.ref||(G.ref={x:W/2,y:H/2-90}),b=G.ball,live=G.state==='play';
 const bx=b.x+(live?b.vx*12:0),by=b.y+(live?b.vy*12:0);
 let tx=clamp(bx-55,X0+30,X1-30),ty=clamp(by+(by<H/2?65:-65),Y0+30,Y1-30);
 if(!live&&G.setp){tx=clamp(b.x-(sd(G.setp.team||0)===0?1:-1)*50,X0+20,X1-20);ty=clamp(b.y+(b.y<H/2?55:-55),Y0+20,Y1-20)}
 let ax=(tx-r.x)*.035,ay=(ty-r.y)*.035;
 for(const p of G.players){if(p.off)continue;const dx=r.x-p.x,dy=r.y-p.y,d=Math.hypot(dx,dy);if(d>0&&d<28){const k=(28-d)/d*.08;ax+=dx*k;ay+=dy*k}}
 {const dx=r.x-b.x,dy=r.y-b.y,d=Math.hypot(dx,dy);if(d>0&&d<34){const k=(34-d)/d*.08;ax+=dx*k;ay+=dy*k}}
 const m=Math.hypot(ax,ay),cap=1.9;if(m>cap){ax*=cap/m;ay*=cap/m}
 r.x=clamp(r.x+ax,X0+10,X1-10);r.y=clamp(r.y+ay,Y0+10,Y1-10);
 /* assistentes: um por linha lateral, ao nível do penúltimo defensor da sua metade (ou da bola, se mais adiantada) */
 const AS=G.asst||(G.asst=[{x:X0+120,y:Y0-13,flag:false,vx:0},{x:X1-120,y:Y1+13,flag:false,vx:0}]);
 for(let i=0;i<2;i++){
  const A=AS[i],dt=i===0?(G.o.homeLeft?0:1):(G.o.homeLeft?1:0);      // equipa que defende a baliza esquerda / direita
  const xs=G.players.filter(p=>!p.off&&p.team===dt).map(p=>Math.abs(p.x-(sd(dt)===0?X0:X1))).sort((a,c)=>a-c);
  const dl=xs.length>1?xs[1]:(xs[0]||200),lineX=sd(dt)===0?X0+dl:X1-dl;
  let t=i===0?Math.min(lineX,b.x):Math.max(lineX,b.x);
  t=i===0?clamp(t,X0+10,W/2+60):clamp(t,W/2-60,X1-10);
  const d=clamp(t-A.x,-1.8,1.8);A.vx=d;A.x+=d;
  A.flag=!!(G.offLine&&performance.now()<G.offLine.until&&((G.offLine.px<W/2)===(i===0)));
 }
}
const refereeStart=startSetPiece;
startSetPiece=function(kind,team,x,y){if(kind==='corner')discipline()[team].corners++;refereeStart(kind,team,x,y);if(kind==='freekick'){G.msg='Livre';G.setp.taker.fx=sd(team)===0?1:-1;G.setp.taker.fy=0}};
const fullStats=statsTable;
statsTable=function(){const laws=discipline(),a=G.o.homeLeft?0:1,b=1-a,rows=[['Faltas','fouls'],['Amarelos','yellow'],['Vermelhos','red'],['Cantos','corners'],['Foras de jogo','offsides']];return fullStats().replace('</tbody>',rows.map(([n,k])=>`<tr><td>${laws[a][k]}</td><td>${n}</td><td>${laws[b][k]}</td></tr>`).join('')+'</tbody>')};
const renderReferee=render;
render=function(){renderReferee();if(!G||G.state==="replay"||G.tut)return;
 const r=G.ref||(G.ref={x:W/2,y:H/2-90}),c=ctx;
 const dx=r.x-(r.px==null?r.x:r.px),dy=r.y-(r.py==null?r.y:r.py);r.px=r.x;r.py=r.y;r.vx=dx;r.vy=dy;r.run=(r.run||0)+Math.hypot(dx,dy)*.28;
 if(Math.hypot(dx,dy)>.15){r.fx=dx/Math.hypot(dx,dy);r.fy=dy/Math.hypot(dx,dy)}else{r.fx=r.fx||1;r.fy=r.fy||0}
 r.role="R";r.num="";r.team=1;r.dash=0;r.tackling=false;r.stun=0;r.sprinting=false;
 if(window.__refSkip&&window.__refSkip())return;
 c.save();TF(c);
 let cx,cy;
 if(PREF.camera==="top"){cx=r.x;cy=r.y-14;c.fillStyle="rgba(0,0,0,.28)";c.beginPath();c.ellipse(r.x+2,r.y+8,10,4,0,0,Math.PI*2);c.fill();c.fillStyle="#151515";c.strokeStyle="#f2b705";c.lineWidth=3;c.beginPath();c.arc(r.x,r.y,9,0,Math.PI*2);c.fill();c.stroke()}
 else{const P=drawHuman(c,r,{c1:"#16181b",c2:"#16181b"},2,false);cx=P.x;cy=P.y-40*P.s*.95}
 if(G.refCard&&G.t<G.refCard.until){c.fillStyle=G.refCard.color;c.fillRect(cx+8,cy-8,6,9)}
 c.restore()};





/* Interface 2026-10-05: navegação funcional com a identidade das propostas. */
function designIcon(kind){
 const paths={season:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 11h18m-9 3v4m-2-2h4"/>',quick:'<circle cx="12" cy="12" r="9"/><path d="m12 7 5 4-2 6H9l-2-6z"/>',cup:'<path d="M7 3h10v6c0 8-10 8-10 0zM7 5H3v3c0 3 2 5 5 5m9-8h4v3c0 3-2 5-5 5m-4 2v5m-4 1h8"/>',challenge:'<circle cx="11" cy="13" r="8"/><circle cx="11" cy="13" r="4"/><path d="m11 13 9-10m-4 0h4v4"/>',tutorial:'<path d="m2 8 10-5 10 5-10 5zM6 10v7c4 3 8 3 12 0v-7m4-2v10"/>',career:'<circle cx="12" cy="7" r="4"/><path d="M4 21v-3c0-8 16-8 16 0v3z"/>',options:'<path d="M3 6h18M3 12h18M3 18h18"/><circle cx="8" cy="6" r="2"/><circle cx="16" cy="12" r="2"/><circle cx="10" cy="18" r="2"/>',data:'<path d="M5 3h10l4 4v14H5zM14 3v5h5M9 12h6m-6 4h6"/>'};
 return `<svg viewBox="0 0 24 24" aria-hidden="true">${paths[kind]||paths.season}</svg>`;
}
function designBrand(screen,label){
 const head=document.createElement('header');head.className='brand-head';
 head.innerHTML=`<button class="brand-home" aria-label="Voltar ao menu principal"><img src="ui/logo-girabola94.png" alt="Girabola 94" class="brand-logo94"></button><p class="brand-caption">Futebol angolano<br>${label}</p>`;
 head.querySelector('button').onclick=showMenu;screen.prepend(head);
}
function designMenu(screen){
 screen.classList.add('menu-screen');
 const art=document.createElement('div');art.className='menu-art';art.setAttribute('aria-hidden','true');screen.appendChild(art);
 const actions=screen.querySelector('.menu-actions');
 const cup=document.getElementById('mCup'),challenge=document.getElementById('mChallenge');
 if(cup){const old=cup.closest('.panel');cup.innerHTML='Taça Girabola <small>Eliminatórias e penáltis</small>';cup.classList.add('ghost');challenge.innerHTML='Desafio <small>Recuperar de 0–1</small>';actions.insertBefore(cup,document.getElementById('mTut'));actions.insertBefore(challenge,document.getElementById('mTut'));old.remove()}
 const map={mCont:'season',mNew:'season',mQuick:'quick',mCup:'cup',mChallenge:'challenge',mTut:'tutorial',mCar:'career',mOpt:'options',mData:'data'};
 actions.querySelectorAll('.btn').forEach(b=>{const icon=document.createElement('span');icon.className='menu-symbol';icon.innerHTML=designIcon(map[b.id]);b.prepend(icon)});
 const how=screen.querySelector('.how');if(how){const details=document.createElement('details');details.className='control-help';details.innerHTML='<summary>Controlos e modos de jogo</summary>';how.parentNode.appendChild(details);details.appendChild(how)}
 const footer=document.createElement('footer');footer.className='menu-footer';footer.innerHTML='<p>16 clubes · Uma paixão</p>';const kits=screen.querySelector('.hero .kits');if(kits)footer.prepend(kits);screen.appendChild(footer);
}
function designPick(screen,mode,first){
 const grid=screen.querySelector('.grid');if(!grid)return;
 const layout=document.createElement('div');layout.className='pick-layout';grid.before(layout);layout.appendChild(grid);
 const cards=Array.from(grid.querySelectorAll('.team'));
 const choose=i=>{
  cards.forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.i===i)));
  const inProg=mode==='season'&&typeof S!=='undefined'&&S&&!seasonDone();
  Pop.team(i,{eyebrow:mode==='quick2'?'Adversário':'O teu clube',noGoal:mode==='quick2',
   yes:(mode==='quick2'?'Preparar jogo':mode==='season'?(inProg?'Substituir e começar':'Começar época'):'Continuar')+' →',
   warn:inProg?`Começar uma nova época apaga a época em curso (<b>${TEAMS[S.my].n}</b>, jornada ${S.round+1} de ${S.fix.length}).`:'',
   onYes:()=>{const b=cards.find(b=>+b.dataset.i===i);b._designChoose()}});
 };
 cards.forEach(b=>{const i=+b.dataset.i;b._designChoose=b.onclick;b.onclick=()=>choose(i);const image=b.querySelector('img');if(image)image.classList.add('team-kit');b.insertAdjacentHTML('afterbegin',crest(i,58))});
 }
function designHub(screen){
 const cols=screen.querySelector('.cols');if(!cols)return;
 const next=Array.from(screen.children).find(e=>e.classList.contains('panel')||e.classList.contains('champ'));
 const objective=Array.from(screen.children).find(e=>e.classList.contains('panel')&&e!==next);
 const last=cols.lastElementChild;
 const body=document.createElement('div');body.className='hub-body';cols.before(body);body.appendChild(cols);
 if(next){next.classList.add('hub-next');body.appendChild(next)}
 if(last)last.classList.add('hub-last');
 if(objective){objective.classList.add('hub-objective');body.appendChild(objective)}
}
function designCup(screen){
 screen.querySelectorAll('.team').forEach(b=>{const i=+b.dataset.cup;const img=b.querySelector('img');if(img)img.classList.add('team-kit');b.insertAdjacentHTML('afterbegin',crest(i,58))});
 if(!CUP)return;
 const box=document.createElement('div');box.className='panel cup-bracket';
 const names=['Oitavos','Quartos','Meias-finais','Final'];
 box.innerHTML=names.map((name,r)=>`<section class="cup-round"><h3>${name}</h3>${r===CUP.round?Array.from({length:CUP.pool.length/2},(_,k)=>{const a=CUP.pool[k*2],b=CUP.pool[k*2+1];return `<div class="cup-tie ${a===CUP.my||b===CUP.my?'mine':''}"><div>${crest(a,24)}${TEAMS[a].n}</div><div>${crest(b,24)}${TEAMS[b].n}</div></div>`}).join(''):`<div class="cup-tie">${r<CUP.round?'Ronda concluída':'Por disputar'}</div>`}</section>`).join('');
 screen.querySelector('.grid').before(box);
}
function designScreen(kind,args){
 const screen=app.querySelector('.screen');if(!screen||screen.querySelector('.brand-head'))return;screen.classList.add(kind+'-screen');
 designBrand(screen,{menu:'Mais que um jogo',pick:'Escolhe o teu caminho',prematch:'Antes do apito',hub:'A tua época',career:'Constrói o teu legado',options:'À tua medida',data:'Dados da época',cup:'Taça Girabola'}[kind]);
 if(kind==='menu')designMenu(screen);
 if(kind==='pick')designPick(screen,args[0],args[1]);
 if(kind==='prematch')screen.querySelectorAll('.side').forEach((side,k)=>{const o=args[0];const i=k===0?(o.homeLeft?o.L:o.R):(o.homeLeft?o.R:o.L);side.insertAdjacentHTML('afterbegin',crest(i,76))});
 if(kind==='hub')designHub(screen);
 if(kind==='cup')designCup(screen);
}
function designOverlay(){
 const card=document.querySelector('#ov .card');if(!card||!G||G.tut)return;
 const s=scoreLine(),a=G.o.homeLeft?G.o.L:G.o.R,b=G.o.homeLeft?G.o.R:G.o.L;
 const identity=document.createElement('div');identity.className='overlay-identity';identity.innerHTML=`${crest(a,66)}<span>${G.teams[s.h].s} · ${G.teams[s.a].s}</span>${crest(b,66)}`;card.prepend(identity);
}
function designPause(){
 const card=document.querySelector('#ov .card');if(!card||!G||G.tut||!G.paused)return;
 card.classList.add('pause-card');
 const opts=Array.from(card.children).filter(e=>e.classList.contains('opt'));
 const roster=opts.pop();if(!roster)return;roster.classList.add('roster');
 const layout=document.createElement('div');layout.className='pause-layout';const left=document.createElement('div');left.className='pause-left';layout.appendChild(left);layout.appendChild(roster);
 const stats=card.querySelector('.mstats');if(stats)left.appendChild(stats);opts.forEach(e=>left.appendChild(e));card.appendChild(layout);
 roster.querySelectorAll('p').forEach(p=>{const button=p.querySelector('[data-sub]');if(!button)return;const player=G.players.find(q=>q.team===0&&q.i===+button.dataset.sub);if(!player)return;p.className='roster-player';const name=document.createElement('span');name.innerHTML=`<strong>${player.name}</strong><small>Força ${player.rating} · energia ${Math.round(player.energy*100)}%</small><span class="roster-energy"><i style="width:${Math.round(player.energy*100)}%"></i></span>`;p.textContent='';p.appendChild(name);p.appendChild(button)});
}
/* Decorar após cada construção: os handlers e dados do jogo são preservados. */
const designOriginal={showMenu,showPick,showPrematch,showHub,showCareer,showOptions,showData,showCup,showOverlay,setPause};
showMenu=function(...args){designOriginal.showMenu(...args);designScreen('menu',args)};
showPick=function(...args){designOriginal.showPick(...args);designScreen('pick',args)};
showPrematch=function(...args){designOriginal.showPrematch(...args);designScreen('prematch',args)};
showHub=function(...args){designOriginal.showHub(...args);designScreen(S?'hub':'menu',args)};
showCareer=function(...args){designOriginal.showCareer(...args);designScreen('career',args)};
showOptions=function(...args){designOriginal.showOptions(...args);designScreen('options',args)};
showData=function(...args){designOriginal.showData(...args);designScreen('data',args)};
showCup=function(...args){designOriginal.showCup(...args);designScreen('cup',args)};
showOverlay=function(...args){designOriginal.showOverlay(...args);designOverlay()};
setPause=function(...args){designOriginal.setPause(...args);if(args[0])designPause()};
window.__gc.setPause=setPause;

const GAME_UI_ASSETS={"stadium":"data:image/webp;base64,","trophy":"data:image/webp;base64,","training":"data:image/webp;base64,","locker":"data:image/webp;base64,"};
/* URLs curtos para evitar limites de tamanho das variáveis CSS. */
for(const key of Object.keys(GAME_UI_ASSETS)){const raw=atob(GAME_UI_ASSETS[key].split(',')[1]);const bytes=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)bytes[i]=raw.charCodeAt(i);GAME_UI_ASSETS[key]=URL.createObjectURL(new Blob([bytes],{type:(GAME_UI_ASSETS[key].match(/^data:([^;,]+)/)||[0,'image/png'])[1]}))}
for(const [name,key] of [['--stadium-art','stadium'],['--locker-art','locker']])document.documentElement.style.setProperty(name,'url("'+GAME_UI_ASSETS[key]+'")');
/* Assets e decoração mantêm botões, handlers e conteúdo dinâmico. */
function coherentScreen(kind){const screen=app.querySelector('.screen');if(!screen)return;screen.dataset.design='girabola-gold';
 const brand=screen.querySelector('.brand-home');if(brand&&!brand.querySelector('.brand-rule'))brand.insertAdjacentHTML('beforeend','<i class="brand-rule" aria-hidden="true"></i>');
 if(kind==='menu'){
  const lede=screen.querySelector('.lede');if(lede)lede.textContent='Escolhe o teu clube. Entra em campo. Conquista o Girabola.';const hero=document.createElement('aside');hero.className='hero-player';hero.setAttribute('aria-hidden','true');hero.innerHTML=kitPreview(S?S.my:0,600);screen.appendChild(hero);
  const art={mCont:'stadium',mNew:'stadium',mQuick:'training',mCup:'stadium',mChallenge:'training',mTut:'training',mCar:'locker',mOpt:'locker'};
  for(const [id,key] of Object.entries(art)){const b=document.getElementById(id);if(b)b.style.setProperty('--tile-art',`url("${GAME_UI_ASSETS[key]}")`)}
 }
 if(kind==='hub'||kind==='career'||kind==='data'||kind==='options'){
  const nav=document.createElement('nav');nav.className='screen-nav';nav.setAttribute('aria-label','Navegação do jogo');
  const items=[['Época','hub',()=>showHub()],['Carreira','career',()=>showCareer()],['Opções','options',()=>showOptions()],['Menu','menu',()=>showMenu()]];
  for(const [name,k,fn] of items){const b=document.createElement('button');b.className='btn ghost'+(kind===k?' on':'');b.textContent=name;b.onclick=fn;nav.appendChild(b)}screen.querySelector('.brand-head').after(nav);
 }
 if(kind==='menu'){const b=document.getElementById('mCup');if(b)b.insertAdjacentHTML('beforeend',`<img class="menu-trophy" src="${GAME_UI_ASSETS.trophy}" alt="" aria-hidden="true">`)}
 if(kind==='hub'){const p=screen.querySelector('.hub-objective');if(p)p.insertAdjacentHTML('afterbegin',`<img class="reward-art" src="${GAME_UI_ASSETS.trophy}" alt="Troféu da época">`)}
 if(kind==='career'){const p=screen.querySelector('.panel');if(p)p.insertAdjacentHTML('afterbegin',`<img class="reward-art" src="${GAME_UI_ASSETS.trophy}" alt="Troféu de carreira">`)}
 if(kind==='options'){
 const snd=document.getElementById('oSnd');if(snd){const panel=document.createElement('div');panel.className='panel';panel.dataset.category='sound';panel.innerHTML='<p class="panel-title">Som do estádio</p><p class="note">Multidão reativa, aplausos e batuque acompanham a partida.</p>';panel.appendChild(snd.closest('label'));screen.appendChild(panel)}
 const panels=Array.from(screen.querySelectorAll('.panel'));for(const p of panels){if(p.dataset.category)continue;const title=(p.querySelector('.panel-title')?.textContent||'').toLowerCase();p.dataset.category=title.includes('teclado')?'controls':title.includes('câmara')?'image':title.includes('precisão')?'game image':'game'}
 const tabs=document.createElement('nav');tabs.className='design-tabs';tabs.setAttribute('aria-label','Categorias das opções');for(const [label,key] of [['Jogo','game'],['Imagem','image'],['Som','sound'],['Controlos','controls']]){const b=document.createElement('button');b.className='btn ghost';b.textContent=label;b.dataset.category=key;b.onclick=()=>{for(const p of panels)p.hidden=!p.dataset.category.split(' ').includes(key);tabs.querySelectorAll('button').forEach(t=>{t.classList.toggle('on',t===b);t.setAttribute('aria-pressed',String(t===b))})};tabs.appendChild(b)}screen.querySelector('.screen-nav').after(tabs);tabs.querySelector('[data-category="game"]').onclick();
 }

}
const coherentOriginal={showMenu,showPick,showPrematch,showHub,showCareer,showOptions,showData,showCup,showOverlay};
for(const [name,kind] of [['showMenu','menu'],['showPick','pick'],['showPrematch','prematch'],['showHub','hub'],['showCareer','career'],['showOptions','options'],['showData','data'],['showCup','cup']]){const fn=(...args)=>{coherentOriginal[name](...args);coherentScreen(kind)};if(name==='showMenu')showMenu=fn;if(name==='showPick')showPick=fn;if(name==='showPrematch')showPrematch=fn;if(name==='showHub')showHub=fn;if(name==='showCareer')showCareer=fn;if(name==='showOptions')showOptions=fn;if(name==='showData')showData=fn;if(name==='showCup')showCup=fn}
showOverlay=function(...args){coherentOriginal.showOverlay(...args);const card=document.querySelector('#ov .card');if(!card)return;const text=card.textContent;if(/Vitória|Campe|Vencedor|Qualificado|superado|Tutorial concluído/i.test(text)){card.classList.add('result-win');card.insertAdjacentHTML('afterbegin',`<img class="result-art" src="${GAME_UI_ASSETS.trophy}" alt="Troféu">`)}};

const assetPause=setPause;
setPause=function(...args){assetPause(...args);if(!args[0])return;document.querySelectorAll('#ov .mstats tr').forEach(row=>{const cells=row.querySelectorAll('td');if(cells.length!==3)return;const a=parseFloat(cells[0].textContent),b=parseFloat(cells[2].textContent);if(!Number.isFinite(a)||!Number.isFinite(b)||a+b===0)return;cells[1].insertAdjacentHTML('beforeend',`<span class="compare-bar" aria-hidden="true"><i style="width:${a/(a+b)*100}%"></i></span>`)});};window.__gc.setPause=setPause;

showMenu();

